export const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: {
    secondSection: [
      {
        id: 'quantity',
        type: 'SingleDataWidget',
        value: state.report.quantity,
        label: 'productsView.details.tabs.sales.pieces',
        visible: showField(state.selectedProduct, 'quantity'),
      },
      {
        id: 'quantityWeight',
        type: 'SingleDataWidget',
        value: `${state.report.quantityWeight} g`,
        label: 'productsView.details.tabs.sales.grams',
        className: 'ml-4',
        visible: showField(state.selectedProduct, 'quantityWeight'),
      },
      {
        id: 'quantityPackage',
        type: 'SingleDataWidget',
        value: state.report.quantityPackage,
        label: 'productsView.details.tabs.sales.packages',
        visible: showField(state.selectedProduct, 'quantityPackage'),
      },
      {
        id: 'quantityUnit',
        type: 'SingleDataWidget',
        value: state.report.quantityUnit,
        label: 'productsView.details.tabs.sales.pieces',
        className: 'ml-4',
        visible: showField(state.selectedProduct, 'quantityUnit'),
      },
    ],
  },
})

const showField = (selectedProduct, fieldId) => {
  if (selectedProduct.factor > 0) {
    return fieldId === 'quantityPackage' || fieldId === 'quantityUnit'
  } else {
    if (fieldId === 'quantity') {
      return true
    }
    if (fieldId === 'quantityWeight') {
      return selectedProduct.isGramaje || selectedProduct.isGramajeFromMLP
    }
  }
}

export default setConfig
