export const setBulkDeletionConfig = state => ({
  isActive: state.isActive,
  itemsToDelete: state.itemsToDelete,
  itemToBeDelete: itemId => {
    const indexFound = state.itemsToDelete.indexOf(itemId)
    if (indexFound >= 0) {
      state.itemsToDelete.splice(indexFound, 1)
      return
    }
    state.itemsToDelete.push(itemId)
  },
  getDeleteSelectConfig: item => {
    if (!state.isActive || !('storeId' in item)) return {}
    const isSelected = state.itemsToDelete.includes(item.id)
    return {
      icon: isSelected ? 'mdi-checkbox-marked' : 'mdi-checkbox-blank-outline',
      iconColor: isSelected ? 'error' : 'accent',
      isSelected,
    }
  },
})
