<template>
  <DialogCard :config="config.dialogData">
    <p class="body-1 textPrimary--text mb-2">
      {{
        getTranslatedText('productsView.history.delete.info', operationTypeText)
      }}
    </p>
    <p class="body-1 textPrimary--text" v-if="infoDeleteOperationText">
      {{ getTranslatedText(infoDeleteOperationText) }}
    </p>
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { stockModificationType } from '@/config/stockModificationsVariables'
import STOCK_MODIFICATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/stockModificationsEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsViewActions from '@/store/productsView/action.types'

import DialogCard from '@/components/shared/DialogCard'
import setConfig from '@/components/ProductDetail/HistoryTab/DeleteStockModifcation/config'
import { updateSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'

export default {
  name: 'DeleteStockModification',
  components: { DialogCard },
  computed: {
    ...mapState('productsView', ['deleteStockModificationOperationDialog']),
    ...mapState('products', { products: state => state.data.products }),
    config() {
      return setConfig(
        {
          isOpen: this.deleteStockModificationOperationDialog.isOpen,
          operationTypeText: this.operationTypeText,
        },
        {
          closeDialog: this.closeDialog,
          deleteOperation: this.deleteStockModificationOperation,
        }
      )
    },
    operationTypeText() {
      if (!this.deleteStockModificationOperationDialog.operation) return ''
      const operationType = this.deleteStockModificationOperationDialog
        .operation.operationType
      if (operationType === stockModificationType.WASTED_PRODUCTS) {
        return this.getTranslatedText(
          'stockModificationTypes.wastedProducts'
        ).toLowerCase()
      }
      return ''
    },
    infoDeleteOperationText() {
      if (!this.deleteStockModificationOperationDialog.operation) return null
      const operationType = this.deleteStockModificationOperationDialog
        .operation.operationType
      if (operationType === stockModificationType.WASTED_PRODUCTS) {
        return 'productsView.history.delete.wastedProductsInfo'
      }
      return null
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('productsView', [
      productsViewActions.setDeleteStockModificationOperationDialog,
    ]),
    ...updateSelectedProductByRoute(),
    closeDialog() {
      this[productsViewActions.setDeleteStockModificationOperationDialog]({
        isOpen: false,
      })
    },
    deleteStockModificationOperation() {
      rendererEventsService.send(STOCK_MODIFICATIONS_DB_API_EVENTS.channel, {
        event: STOCK_MODIFICATIONS_DB_API_EVENTS.events.delete.name,
        data: {
          operation: this.deleteStockModificationOperationDialog.operation,
        },
      })
    },
    stockModificationsListener(event, payload) {
      const stockModificationsEvents = STOCK_MODIFICATIONS_DB_API_EVENTS.events
      const replies = {
        [stockModificationsEvents.delete.replies.success]: () => {
          notificationsService.showSuccess(payload.message, this.$vuetify.lang)
        },
        [stockModificationsEvents.delete.replies.error]: () => {
          notificationsService.showError(
            payload.data.error.message,
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    productStoreWasUpdatedListener(fromEvent) {
      if (fromEvent !== 'deleteStockModification') return
      this.setSelectedProduct(
        this.getProductFromProductsList(
          this.deleteStockModificationOperationDialog.operation.productId
        )
      )
      this.closeDialog()
    },
    getProductFromProductsList(id) {
      return this.products.find(product => product.id === id)
    },
  },
  beforeMount() {
    this.$root.$on('productDetailTabsWasChanged', this.closeDialog)
    this.$root.$on(
      'productStoreWasUpdated',
      this.productStoreWasUpdatedListener
    )
    rendererEventsService.subscribe(
      STOCK_MODIFICATIONS_DB_API_EVENTS.replyChannel,
      this.stockModificationsListener
    )
  },
  beforeDestroy() {
    this.$root.$off('productDetailTabsWasChanged', this.closeDialog)
    this.$root.$off(
      'productStoreWasUpdated',
      this.productStoreWasUpdatedListener
    )
    rendererEventsService.removeListener(
      STOCK_MODIFICATIONS_DB_API_EVENTS.replyChannel,
      this.stockModificationsListener
    )
  },
}
</script>
