<template>
  <v-card flat color="cardBackgroundPrimary">
    <div :class="['pt-6 d-flex flex-column', expandedVariant]">
      <div v-for="widget in componentConfig.widgets" :key="widget.id">
        <component
          :is="widget.type"
          :opened="widgets[widget.id]"
          :onClickDropDown="widget.onClickDropDown"
        />
      </div>
    </div>
  </v-card>
</template>

<script>
import { mapState } from 'vuex'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import setConfig from '@/components/ProductDetail/DetailsTab/config'
import StockDetails from '@/components/ProductDetail/DetailsTab/StockDetails'
import MainDetails from '@/components/ProductDetail/DetailsTab/MainDetails'
import PackageDetails from '@/components/ProductDetail/DetailsTab/PackageDetails'

export default {
  name: 'DetailsTab',
  components: {
    StockDetails,
    MainDetails,
    PackageDetails,
  },
  data() {
    return {
      widgets: {},
    }
  },
  computed: {
    ...mapState('app', ['windowSize']),
    ...getSelectedProductByRoute(),
    componentConfig: function() {
      return setConfig(
        { selectedProduct: this.selectedProduct },
        { toggleWidgetDropDown: this.toggleWidgetDropDown }
      )
    },
    expandedVariant() {
      return this.windowSize.y <= 935 ? 'expanded-variant' : ''
    },
  },
  methods: {
    setWidgetsProperties: function() {
      this.componentConfig.widgets.forEach(widget =>
        this.$set(this.widgets, widget.id, null)
      )
    },
    toggleWidgetDropDown(widget) {
      this.widgets[widget] = !this.widgets[widget]
      const widgetsOpened = Object.values(this.widgets).filter(
        value => value === true
      ).length
      if (widgetsOpened > this.componentConfig.maxWidgetsOpened) {
        const toClose = Object.keys(this.widgets)
        toClose.splice(toClose.indexOf(widget), 1)
        this.widgets[
          toClose[Math.floor(Math.random() * toClose.length)]
        ] = false
      }
    },
  },
  watch: {
    windowSize(newSize, oldSize) {
      if (oldSize.y > 935 && newSize.y <= 935) {
        let opened = this.componentConfig.maxWidgetsOpened
        Object.keys(this.widgets).forEach(key => {
          this.widgets[key] = opened > 0 ? true : false
          opened--
        })
      } else if (oldSize.y <= 935 && newSize.y > 935) {
        Object.keys(this.widgets).forEach(key => (this.widgets[key] = null))
      }
    },
  },
  mounted() {
    this.setWidgetsProperties()
    if (this.windowSize.y <= 935) {
      let opened = this.componentConfig.maxWidgetsOpened
      Object.keys(this.widgets).forEach(key => {
        this.widgets[key] = opened > 0 ? true : false
        opened--
      })
    } else {
      Object.keys(this.widgets).forEach(key => (this.widgets[key] = null))
    }
  },
}
</script>

<style lang="scss" scoped>
.expanded-variant {
  height: 350px;
  overflow: hidden;
}
</style>
