import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

export const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: [
    {
      id: 'quantity',
      type: 'SingleDataWidget',
      value: formatNumberFromDbToCurrency(state.report.income),
      label: 'productsView.details.tabs.sales.income',
      visible: true,
    },
    {
      id: 'quantityPackage',
      type: 'SingleDataWidget',
      value: formatNumberFromDbToCurrency(state.report.profit),
      label: 'productsView.details.tabs.sales.profit',
      visible: true,
    },
  ],
})

export default setConfig
