<template>
  <v-btn
    v-if="showButton"
    small
    text
    color="primary"
    class="ml-2"
    @click="downloadHomeCodes"
    v-track:click="{
      category: 'Products',
      screen: 'PaginatedCards',
      name: 'Download home codes',
    }"
  >
    <v-icon class="mr-1">mdi-download</v-icon>
    {{ getTranslatedText('productsView.homeCodes.buttonDownload') }}
  </v-btn>
</template>

<script>
import { mapGetters } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import countries from '@/config/countries'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

export default {
  name: 'DownloadHomeCodes',
  computed: {
    showButton() {
      return [countries.CO.localeIsoCode, countries.MX.localeIsoCode].includes(
        this.getCountry().localeIsoCode
      )
    },
  },
  methods: {
    ...mapGetters('account', ['getCountry']),
    getTranslatedText,
    downloadHomeCodes() {
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.downloadHomeCodes.name,
        data: {
          countryCode: this.getCountry().localeIsoCode,
        },
      })
    },
    downloadHomeCodesListener(event, payload) {
      const events = STORE_INVENTORY_DB_API_EVENTS.events
      const replies = {
        [events.downloadHomeCodes.replies.success]: () => {
          notificationsService.showOpenFolder(
            payload.data.filePath,
            'shared.fileDownloaded',
            this.$vuetify.lang,
            {
              timeout: 8000,
            }
          )
        },
        [events.downloadHomeCodes.replies.error]: () => {
          notificationsService.showError(
            `productsView.homeCodes.error.${payload.data.message}`,
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  mounted() {
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.downloadHomeCodesListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.downloadHomeCodesListener
    )
  },
}
</script>
