<template>
  <v-card flat :class="className" color="cardBackgroundPrimary">
    <v-tabs
      v-model="tab"
      :background-color="backgroundColor"
      grow
      icons-and-text
      :color="textColor"
      @change="$emit('change')"
    >
      <v-tab
        v-for="element in tabs"
        :key="element.id"
        :href="`#tab-${element.id}`"
        v-track:click="{
          category: $route.name,
          screen: trackScreen,
          name: `Go to tab ${element.component.name}`,
        }"
      >
        {{ element.name }}
        <v-icon>{{ element.icon }}</v-icon>
      </v-tab>
    </v-tabs>

    <v-tabs-items v-model="tab" class="items">
      <v-tab-item
        v-for="element in tabs"
        :key="element.id"
        :value="`tab-${element.id}`"
      >
        <component v-bind:is="element.component"></component>
      </v-tab-item>
    </v-tabs-items>
  </v-card>
</template>

<script>
export default {
  name: 'Tabs',
  props: {
    tabs: {
      type: Array,
      required: true,
    },
    backgroundColor: {
      type: String,
      default: 'primary',
    },
    textColor: {
      type: String,
      default: 'white',
    },
    className: {
      type: String,
      default: '',
    },
    trackScreen: {
      type: String,
      required: true,
    },
  },
  data() {
    return {
      tab: 'tab-0',
    }
  },
}
</script>
