import ProductCard from '@/components/shared/ProductCard'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const setConfig = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: item => methods.onClickCard(item),
    onDblClick: () => null,
  },
  containerRef: 'products-view__products-list',
  component: ProductCard,
  title: 'productsView.listView.title',
  icon: 'mdi-fridge-outline',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  groups: [
    {
      id: 'all',
      icon: 'mdi-view-module',
      title: 'productsView.toolbar.buttons.all',
    },
    {
      id: 'services',
      icon: 'mdi-cellphone-arrow-down',
      title: 'productsView.toolbar.buttons.services',
    },
    {
      id: 'byWeight',
      icon: 'mdi-weight',
      title: 'productsView.toolbar.buttons.byWeight',
    },
    {
      id: 'openProducts',
      icon: 'mdi-package-variant',
      title: 'productsView.toolbar.buttons.openProducts',
    },
    {
      id: 'favorites',
      icon: 'mdi-cards-heart',
      title: 'productsView.toolbar.buttons.favorites',
    },
    {
      id: 'productsSimilarUpc',
      icon: 'mdi-alert',
      title: 'productsView.toolbar.buttons.productsSimilarUpc',
    },
    {
      id: 'search',
      icon: 'mdi-magnify',
      title: 'productsView.toolbar.buttons.search',
    },
    {
      id: 'superCategories',
      icon: 'mdi-tag-outline',
      title: 'productsView.toolbar.buttons.superCategories',
    },
    {
      id: 'scan',
      icon: 'mdi-barcode',
      title: 'productsView.toolbar.buttons.scan',
    },
    {
      id: 'noStock',
      icon: 'mdi-package-variant-remove',
      title: 'productsView.toolbar.buttons.noStock',
    },
    {
      id: 'lowStock',
      icon: 'mdi-package-variant-minus',
      title: 'productsView.toolbar.buttons.lowStock',
    },
  ],
  sortBy: 'name',
  sortDesc: false,
  isDetail: false,
  sort: {
    by: [
      { prop: 'name', text: 'productsView.listView.sortBy.name' },
      { prop: 'price', text: 'productsView.listView.sortBy.price' },
      {
        prop: 'quantity',
        text: 'productsView.listView.sortBy.quantity',
      },
      { prop: 'upc', text: 'productsView.listView.sortBy.upc' },
    ],
    sortBy: state.sortBy,
    sortDesc: state.sortDesc,
    iconColor: 'accent',
  },
  rowsPerPage: 4,
  page: 1,
  cardComponents: {
    ProductCard: {
      cardOffsetHeight: 122,
      component: ProductCard,
      itemsPerRow: {
        small: 2,
        medium: 3,
        large: 4,
        extraLarge: 6,
      },
      truncate: {
        lg: '50',
        xl: '100',
      },
    },
  },
  noDataMessage: {
    icon: 'mdi-barcode-scan',
    messages: [
      'productsView.listView.noData.firstMessage',
      'productsView.listView.noData.secondMessage',
    ],
  },
})

export default setConfig
