import { integer, required } from 'vuelidate/lib/validators'

const INPUT_PACKS = 'packs'
const INPUT_PIECES = 'pieces'
const INPUT_BY_WEIGHT = 'byWeight'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    id: 'wasted-product-form',
    icon: 'mdi-basket-unfill',
    title: 'productsView.wastedProducts.create',
    titleBackground: '',
    titleColor: 'textPrimary',
    messages: ['productsView.wastedProducts.info'],
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: 500,
    acceptButtonText: 'shared.accept',
    isAcceptButtonDisabled: state.v.$invalid,
    onClickCancel: () => methods.cancel(),
    onClickAccept: () => methods.accept(),
  },
  fields: getFieldsByProduct(state, methods),
})

const getFieldsByProduct = (state, methods) => {
  const piecesInput = {
    id: INPUT_PIECES,
    type: 'input',
    valueType: 'number',
    step: 1,
    label: 'productsView.wastedProducts.piecesLabel',
    autofocus: true,
    onFocus: $event => $event.target.select(),
    onEnterKey: $event => getHandleKeyPress($event, methods),
    errorMessage: getErrorMessage(INPUT_PIECES, state.v),
    oneLine: true,
    required: true,
    validators: {
      required,
      integer,
      minValue: value => value > 0,
      maxValue: value =>
        value <= getMaxValue(INPUT_PIECES, state.selectedProduct, state.inputs),
    },
  }
  if (state.selectedProduct.factor > 0) {
    return [
      {
        id: INPUT_PACKS,
        type: 'input',
        valueType: 'number',
        step: 1,
        label: 'productsView.wastedProducts.packsLabel',
        autofocus: true,
        onFocus: $event => $event.target.select(),
        onEnterKey: $event => getHandleKeyPress($event, methods),
        errorMessage: getErrorMessage(INPUT_PACKS, state.v),
        required: true,
        validators: {
          required,
          integer,
          minValue: value =>
            state.inputs[INPUT_PIECES] > 0 ? value >= 0 : value > 0,
          maxValue: value =>
            value <=
            getMaxValue(INPUT_PACKS, state.selectedProduct, state.inputs),
        },
      },
      {
        ...piecesInput,
        autofocus: false,
        onFocus: () => null,
        oneLine: false,
        validators: {
          ...piecesInput.validators,
          minValue: value =>
            state.inputs[INPUT_PACKS] > 0 ? value >= 0 : value > 0,
        },
      },
    ]
  }
  if (state.selectedProduct.isGramaje === 1) {
    return [
      {
        id: INPUT_BY_WEIGHT,
        type: 'input',
        valueType: 'number',
        step: 1,
        label: 'productsView.wastedProducts.gramajeLabel',
        autofocus: true,
        onFocus: $event => $event.target.select(),
        onEnterKey: $event => getHandleKeyPress($event, methods),
        errorMessage: getErrorMessage(INPUT_BY_WEIGHT, state.v),
        oneLine: true,
        required: true,
        validators: {
          required,
          integer,
          minValue: value => value > 0,
          maxValue: value =>
            value <=
            getMaxValue(INPUT_BY_WEIGHT, state.selectedProduct, state.inputs),
        },
      },
    ]
  }
  return [{ ...piecesInput }]
}

const getHandleKeyPress = ($event, methods) => {
  $event.preventDefault()
  methods.accept()
}

const getMaxValue = (inputValue, selectedProduct, inputs) => {
  switch (inputValue) {
    case INPUT_PACKS:
      if (inputs[INPUT_PIECES] <= 0) {
        return Math.floor(selectedProduct.quantity / selectedProduct.factor)
      }
      if (Number(inputs[INPUT_PACKS]) === 0) return 0
      return Math.floor(
        (selectedProduct.quantity - Number(inputs[INPUT_PIECES])) /
          selectedProduct.factor
      )
    case INPUT_PIECES: {
      if (selectedProduct.factor <= 0) return selectedProduct.quantity
      if (inputs[INPUT_PACKS] <= 0) return selectedProduct.quantity
      if (Number(inputs[INPUT_PIECES]) === 0) return 0
      return (
        selectedProduct.quantity -
        Number(inputs[INPUT_PACKS]) * selectedProduct.factor
      )
    }
    default:
      return selectedProduct.quantity
  }
}

const getErrorMessage = (inputValue, v) => {
  if (!v[inputValue]) return ''
  if (!v[inputValue].required) {
    return 'productsView.wastedProducts.requiredError'
  }
  if (!v[inputValue].minValue) {
    return 'productsView.wastedProducts.minValueError'
  }
  if (!v[inputValue].maxValue) {
    return 'productsView.wastedProducts.maxValueError'
  }
  return 'productsView.wastedProducts.valueError'
}

export default setConfig
