<template>
  <div class="d-flex flex-column">
    <div :class="config.reverse ? 'd-flex justify-end' : 'd-flex'">
      <FormattedText
        intl
        :value="config.label"
        type="text-subtitle-2"
        :class="!config.reverse ? 'label-padding' : ''"
      />
      <v-icon
        :color="config.iconColor ? config.iconColor : 'cardPrimary'"
        small
        class="pl-2"
        @click="editField()"
      >
        {{ config.labelIcon }}
      </v-icon>
    </div>
    <div :class="['d-flex', config.reverse ? 'justify-end' : '']">
      <div
        @click="editField()"
        v-if="!editing"
        :id="`edit-field-${this.config.id}`"
      >
        <FormattedText
          :value="config.textFormatter(value)"
          type="text-h6"
          :color="config.valueTextColor"
          :class="['text-field', config.reverse ? 'text-end pr-1' : '']"
        />
      </div>
      <v-text-field
        v-if="editing"
        v-model="value"
        :type="config.editTextType === undefined ? 'text' : config.editTextType"
        flat
        background-color="cardBackgroundPrimary"
        solo
        dense
        hide-details
        :class="
          `edit-field-${
            config.editTextColor === undefined
              ? 'productPrimary'
              : config.editTextColor
          }`
        "
        autofocus
        :reverse="config.reverse"
        @change="updateField()"
        @blur="updateField()"
        @focus="$event.target.select()"
      />
      <DialogCard
        v-if="config.dialogConfig !== undefined"
        :config="dialogConfig.dialogData"
      />
    </div>
  </div>
</template>

<script>
import { removeEmojis } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'SingleEditDataWidget',
  components: {
    FormattedText,
    DialogCard,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      editing: false,
      dialogOpened: false,
    }
  },
  computed: {
    value: {
      get: function() {
        return 'numberFormatter' in this.config
          ? this.config.numberFormatter(this.config.value)
          : this.config.value
      },
      set: function(newValue) {
        this.config.onInputChange(removeEmojis(newValue))
      },
    },
    dialogConfig: function() {
      return this.config.dialogConfig(
        { opened: this.dialogOpened },
        {
          closeDialog: () => (this.dialogOpened = false),
          enableEdit: () => (this.editing = true),
        },
        {
          title: this.config.warningMessageTitle,
          messages: this.config.warningMessages,
        }
      )
    },
  },
  methods: {
    editField() {
      this.config.dialogConfig !== undefined
        ? (this.dialogOpened = true)
        : (this.editing = true)
    },
    updateField() {
      if (this.config.valueLimit && this.config.valueLimit < this.value)
        this.config.onInputChange(this.config.valueLimit)
      if (this.config.valueLimit && -this.config.valueLimit > this.value)
        this.config.onInputChange(-this.config.valueLimit)
      this.editing = false
      this.config.onInputFinishEdit()
    },
  },
  mounted() {
    if (this.config.editing) {
      setTimeout(() => {
        const editField = document.getElementById(
          `edit-field-${this.config.id}`
        )
        if (editField != undefined) editField.click()
      }, 150)
    }
  },
}
</script>

<style lang="scss" scoped>
$colors: 'productPrimary', 'customerPrimary';
$widths: 80px, 250px;

@each $color in $colors {
  $i: index($colors, $color);
  .edit-field-#{$color} {
    border-radius: 8px;
    font-size: 1.25rem;
    font-weight: 500;
    width: nth($widths, $i);
    :deep(.v-input__control) {
      min-height: 20px !important;
      .v-input__slot {
        padding-left: 4px !important;
        padding-right: 4px !important;
        input {
          color: var(--v-#{$color}-base);
        }
      }
    }
  }
}
.text-field {
  border-radius: 8px;
  font-size: 1.25rem;
  font-weight: 500;
}
.label-padding {
  padding-left: 2px;
}
</style>
