<template>
  <v-container fluid>
    <v-row class="px-3">
      <FormattedText
        intl
        value="productsView.importProductsDialog.stepper.steps.step1.introduction"
        typeText="text-body-1"
      />
    </v-row>
    <v-row>
      <v-col cols="12">
        <div class="d-flex justify-center">
          <div class="download-link-tt d-flex align-center">
            <v-icon color="primary" large>mdi-microsoft-excel</v-icon>
            <a @click="handleDownload" class="ml-2 text-none">
              <FormattedText
                intl
                value="productsView.importProductsDialog.stepper.steps.step1.template"
                color="primary"
              />
            </a>
          </div>
        </div>
      </v-col>
    </v-row>
    <v-row>
      <v-col cols="12">
        <FormattedText
          intl
          value="productsView.importProductsDialog.stepper.steps.step1.paragraph"
          typeText="text-body-1"
        />
      </v-col>
      <v-col cols="12">
        <FormattedText
          intl
          value="productsView.importProductsDialog.stepper.steps.step1.stepsToContinue"
          typeText="text-body-1"
        />
      </v-col>
      <v-col cols="12">
        <ul>
          <li v-for="{ step, text } in flowSteps" :key="step">
            <FormattedText intl :value="text" typeText="text-body-1" />
          </li>
        </ul>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'Instructions',
  components: { FormattedText },
  data() {
    return {
      flowSteps: [
        {
          step: 1,
          text: 'productsView.importProductsDialog.stepper.steps.step1.step1',
        },
        {
          step: 2,
          text: 'productsView.importProductsDialog.stepper.steps.step1.step2',
        },
        {
          step: 3,
          text: 'productsView.importProductsDialog.stepper.steps.step1.step3',
        },
      ],
    }
  },
  methods: {
    handleDownload() {
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.downloadTemplate.name,
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.download-link-tt {
  --ds-shadow-raised: 0px 1px 1px #091e4240, 0px 0px 1px #091e424f;
  background-color: var(--v-cardBackgroundPrimary-base);
  border-radius: 3px;
  box-shadow: var(
    --ds-shadow-raised,
    #091e4240 0 1px 1px,
    #091e4221 0 0 1px 1px
  );
  cursor: pointer;
  display: inline-block;
  line-height: 14px;
  padding: 1px 0.24em 2px;
  font-size: 1.5rem;
  font-weight: bold;
  -webkit-user-select: text;
  user-select: text;
}
</style>
