<template>
  <component :is="component" :bulkDeletionConfig="bulkDeletionConfig" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import appActions from '@/store/app/actions.types'
import productsViewActions from '@/store/productsView/action.types'

// TODO: Import dynamically the components
import PaginatedCards from '@/components/ProductsView/ProductsList/PaginatedCards'
import PaginatedTable from '@/components/ProductsView/ProductsList/PaginatedTable'
import { setBulkDeletionConfig } from '@/components/ProductsView/ProductsList/config'

export default {
  name: 'ProductsList',
  components: {
    PaginatedCards,
    PaginatedTable,
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
    }),
    ...mapState('productsView', [
      'component',
      'productDetailDialog',
      'bulkDeletion',
    ]),
    bulkDeletionConfig() {
      return setBulkDeletionConfig({
        isActive: this.bulkDeletion.isActive,
        itemsToDelete: this.bulkDeletion.itemsToDelete,
      })
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('productsView', [
      productsViewActions.setGroupFilter,
      productsViewActions.setSearchTermFilter,
      productsViewActions.setSuperCategoriesFilter,
    ]),
  },
}
</script>
