<template>
  <v-hover>
    <template>
      <v-card
        flat
        color="cardBackground"
        class="card-container rounded-lg"
        :style="cssVars"
      >
        <div class="product-info">
          <div class="product-icon">
            <CategoryIcon
              :categoryName="data.categoryName"
              :iconSize="{ x: 45, y: 45 }"
            />
          </div>
          <div class="product-stock">
            <div class="stat-widget">
              <p
                v-if="isSLPProduct"
                class="text-caption textOverWhiteBackground--text font-weight-bold mb-0 text-center"
                v-html="stock"
              />
              <v-icon v-if="!isSLPProduct" color="white">
                mdi-plus-circle
              </v-icon>
            </div>
          </div>
        </div>
        <div class="product-detail">
          <div class="selected" v-if="checkIfCardIsSelected">
            <v-icon color="checkIcon" class="pr-1">mdi-check-circle</v-icon>
          </div>
          <div
            class="selected"
            v-else-if="!!Object.keys(deleteSelectConfig).length"
          >
            <v-icon :color="deleteSelectConfig.iconColor" class="pr-1">
              {{ deleteSelectConfig.icon }}
            </v-icon>
          </div>
          <div class="selected" v-else>
            <v-tooltip bottom v-if="productsSimilarUpc[data.id]">
              <template v-slot:activator="{ on }">
                <v-btn
                  v-on="on"
                  color="warning"
                  icon
                  class="mr-1 mt-n1"
                  small
                  @click.prevent.stop="showSimilarProductsUpc(data)"
                  v-track:click="{
                    category: $route.name,
                    screen: 'ProductCard',
                    name: 'Show similar products upc',
                  }"
                >
                  <v-icon>mdi-alert</v-icon>
                </v-btn>
              </template>
              <span>{{ getTranslatedText('productCard.similarUpc') }}</span>
            </v-tooltip>
            <v-tooltip bottom>
              <template v-slot:activator="{ on }">
                <v-btn
                  v-on="on"
                  v-if="data.isStoreInventory"
                  :color="data.isStarred ? 'cardFavorite' : 'accent'"
                  icon
                  class="mr-1 mt-n1"
                  small
                  @click.prevent.stop="changeFavoriteStatus(data)"
                >
                  <v-icon>
                    {{
                      data.isStarred ? 'mdi-cards-heart' : 'mdi-heart-outline'
                    }}
                  </v-icon>
                </v-btn>
              </template>
              <span>{{
                getTranslatedText(
                  `productCard.${data.isStarred ? 'un' : ''}markStarred`
                )
              }}</span>
            </v-tooltip>
          </div>
          <div class="product-description">
            <FormattedText
              :value="getProductDescription(data)"
              className="font-weight-bold"
              shorter
              :shorterValue="trucateLength"
            />
            <FormattedText
              :value="soldBy"
              className="font-italic"
              color="textSecondary"
              type="text-caption"
            />
          </div>
          <div class="product-stats">
            <div class="stat-widget pr-2">
              <v-icon :color="iconColor" class="pr-1">
                mdi-barcode-scan
              </v-icon>
              <span v-if="data.isGramaje === 0">{{ data.upc }}</span>
            </div>
            <v-spacer></v-spacer>
            <div class="stat-widget">
              <span class="pr-1">
                {{ getProductPrice(data) }}
              </span>
              <v-icon :color="iconColor">mdi-poll-box</v-icon>
            </div>
          </div>
        </div>
        <v-fade-transition>
          <v-overlay
            v-if="checkIfCardIsSelected || deleteSelectConfig.isSelected"
            absolute
            :color="
              deleteSelectConfig.isSelected
                ? 'rgba(255, 138, 128, 0.50)'
                : 'rgba(216, 252, 174, 0.50)'
            "
          />
        </v-fade-transition>
      </v-card>
    </template>
  </v-hover>
</template>

<script>
import { isNil } from 'ramda'
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import { storeInventory } from '@/config/storeMapper'

import { getTranslatedText, mapStoreObject } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'

import FormattedText from '@/components/shared/FormattedText'
import CategoryIcon from '@/components/shared/CategoryIcon'

export default {
  name: 'ProductCard',
  components: { FormattedText, CategoryIcon },
  props: {
    data: {
      type: Object,
      required: true,
      default: () => ({
        id: 1,
        price: '$23.12',
        description: 'Chocolate Hello My Name Is Sweet Popcorn 100gr',
        upc: '009542018399',
        stock: 12,
        soldIn: 'uds',
      }),
    },
    selected: {
      type: Object,
      default: null,
    },
    truncate: {
      type: Object,
      default: null,
    },
    deleteSelectConfig: {
      type: Object,
      default: () => ({}),
    },
  },
  computed: {
    ...mapState('products', {
      productsSimilarUpc: state => state.data.productsSimilarUpc,
    }),
    checkIfCardIsSelected() {
      if (this.selected) {
        return this.selected.id === this.data.id
      }
      return false
    },
    trucateLength() {
      switch (this.$vuetify.breakpoint.name) {
        case 'lg':
          return this.truncate.lg
        case 'xl':
          return this.truncate.xl
        default:
          return '50'
      }
    },
    soldBy() {
      const product = this.data
      const startText = this.getTranslatedText('productsView.details.soldBy')
      if (product.isGramaje === 1) {
        return `${startText} ${this.getTranslatedText(
          'productsView.details.byWeight'
        )}`
      } else if (product.factor > 1 && product.factorSalesBy === 0) {
        return `${startText} ${this.getTranslatedText(
          'productsView.details.package'
        )}`
      } else if (product.factor > 1 && product.factorSalesBy === 1) {
        return `${startText} ${this.getTranslatedText(
          'productsView.details.piece'
        )}`
      } else if (product.factor > 1 && product.factorSalesBy === 2) {
        return `${startText} ${this.getTranslatedText(
          'productsView.details.soldByAsk'
        )}`
      }
      return `${startText} ${this.getTranslatedText(
        'productsView.details.piece'
      )}`
    },
    cssVars() {
      const cardStyles = {
        active: {
          '--primary-bg-color': `var(--v-productCardAvailableSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardAvailablePrimary-base)`,
        },
        warning: {
          '--primary-bg-color': `var(--v-productCardWarningSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardWarningPrimary-base)`,
        },
        out: {
          '--primary-bg-color': `var(--v-productCardOutSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardOutPrimary-base)`,
        },
        inactive: {
          '--primary-bg-color': `var(--v-productCardInactiveSecondary-base)`,
          '--secondary-bg-color': `var(--v-productCardInactivePrimary-base)`,
        },
      }
      return isNil(this.data.isStoreInventory) ||
        this.data.isStoreInventory === 1
        ? cardStyles[`${this.getProductLevel(this.data)}`]
        : cardStyles.inactive
    },
    iconColor() {
      return isNil(this.data.isStoreInventory) ||
        this.data.isStoreInventory === 1
        ? this.getIconColor(this.data)
        : 'productCardInactivePrimary'
    },
    quantity() {
      return !isNil(this.data.quantity) ? this.data.quantity : 0
    },
    isSLPProduct() {
      return this.data.isStoreInventory
    },
    stock() {
      const factor = this.data.factor
      const stockRaw = this.data.quantity
      if (factor > 1) {
        const pack =
          factor === 0
            ? Math.floor(stockRaw) | 0
            : Math.floor(stockRaw / factor) | 0
        const pieces = stockRaw % factor
        return `${pack} paq <br/> ${pieces} pzs`
      } else if (this.data.isGramaje === 1) {
        return `${stockRaw} g`
      }
      return `${stockRaw} uds`
    },
  },
  methods: {
    ...mapActions('products', [productsActions.updateProductByProperties]),
    ...mapActions('productsView', [
      productsViewActions.setSimilarProductsUpcDialog,
    ]),
    getTranslatedText,
    getCategoryURL: function(name) {
      return require(`@/assets/superCategories/${name}.svg`)
    },
    getProductDescription: function(data) {
      return `${data.name.toString()} ${data.alternativeName.toString()}`.trim()
    },
    getProductPrice(product) {
      if (product.isGramaje === 1)
        return formatNumberFromDbToCurrency(product.price)
      if (product.isGramaje === 0 && product.factor <= 0)
        return formatNumberFromDbToCurrency(product.price)
      if (product.factor > 0 && product.factorSalesBy === 2) return '?'
      if (product.factor > 0 && product.factorSalesBy !== 2) {
        switch (product.factorSalesBy) {
          case 0:
            return formatNumberFromDbToCurrency(this.data.price)
          case 1:
            return formatNumberFromDbToCurrency(this.data.unitProdPrice)
        }
      }
    },
    getProductLevel(product) {
      if (product.quantity > product.levelWarning) return 'active'
      if (product.quantity > 0 && product.quantity <= product.levelWarning)
        return 'warning'
      if (product.quantity <= 0) return 'out'
      return 'inactive'
    },
    getIconColor(product) {
      if (product.quantity > product.levelWarning)
        return 'productCardAvailablePrimary'
      if (product.quantity > 0 && product.quantity <= product.levelWarning)
        return 'productCardWarningPrimary'
      if (product.quantity <= 0) return 'productCardOutPrimary'
      return 'productCardInactivePrimary'
    },
    changeFavoriteStatus(product) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ProductCard',
        name: `${product.isStarred ? 'Unmark' : 'Mark'} favorite product`,
      })
      const newValue = product.isStarred === 1 ? 0 : 1
      this[productsActions.updateProductByProperties]({
        _id: product.id,
        is_starred: newValue,
      })
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data: {
          productToUpdated: {
            id: product.id,
            data: mapStoreObject({ isStarred: newValue }, storeInventory, true),
          },
        },
      })
    },
    showSimilarProductsUpc(product) {
      this[productsViewActions.setSimilarProductsUpcDialog]({
        isOpen: true,
        product,
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.card-container {
  display: flex;
  overflow: hidden;
  &:hover {
    cursor: pointer;
    .product-info {
      .product-icon {
        :deep(img) {
          -webkit-filter: brightness(0) invert(1);
          filter: brightness(0) invert(1);
          z-index: 1;
        }
        &:before {
          transform: scaleY(1);
        }
      }
    }
  }
  .product-info {
    flex-direction: column;
    width: 80px;
    .product-icon {
      display: flex;
      background-color: var(--primary-bg-color);
      width: 80px;
      height: 70px;
      align-items: center;
      justify-content: center;
      &::before {
        content: '';
        position: absolute;
        z-index: 0;
        width: 80px;
        top: 0;
        left: 0;
        right: 0;
        bottom: 35px;
        background: var(--secondary-bg-color);
        transform: scaleY(0);
        -webkit-transform-origin: 50% 100%;
        transform-origin: 50% 100%;
        -webkit-transition-property: transform;
        transition-property: transform;
        -webkit-transition-duration: 0.2s;
        transition-duration: 0.2s;
        -webkit-transition-timing-function: ease-out;
        transition-timing-function: ease-out;
      }
    }
    .product-stock {
      display: flex;
      width: 80px;
      height: 35px;
      background-color: var(--secondary-bg-color);
      align-items: center;
      justify-content: center;
      p {
        line-height: 1.45;
      }
    }
  }
  .product-detail {
    display: flex;
    flex-direction: column;
    width: 100%;
    line-height: 1.3;
    .selected {
      position: absolute;
      right: 6px;
      top: 10px;
    }
    .product-description {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 8px 80px 0 14px;
      height: 70px;
    }
    .product-stats {
      display: flex;
      padding: 8px 10px 8px 14px;
      height: 35px;
      align-items: center;
      .stat-widget {
        display: flex;
        align-items: center;
      }
    }
  }
}
</style>
