<template>
  <v-container fluid>
    <v-row>
      <FormattedText
        intl
        value="productsView.importProductsDialog.stepper.steps.step2.remember"
        typeText="text-body-1"
      />
    </v-row>
    <transition name="fade">
      <v-row
        class="mt-4 d-flex justify-center align-center fill-height"
        v-if="!isLoading"
      >
        <FileInputWithDropArea
          :validTypes="validTypes"
          @files-updated="handleFilesUpdated"
          :isLoading="isLoading"
        />
      </v-row>
    </transition>
    <transition name="fade">
      <v-row
        class="mt-4 d-flex justify-center align-center fill-height text-center"
        v-if="isLoading"
      >
        <p>
          <FormattedText
            intl
            value="productsView.importProductsDialog.stepper.steps.step2.importMessage"
            typeText="text-body-1"
          />
          <FormattedText
            intl
            value="productsView.importProductsDialog.stepper.steps.step2.waitMessage"
            typeText="text-body-1"
          />
        </p>
      </v-row>
    </transition>
  </v-container>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'
import FileInputWithDropArea from '@/components/shared/FileInputWithDropArea'

export default {
  name: 'UploadFile',
  components: { FormattedText, FileInputWithDropArea },
  props: {
    isLoading: {
      type: Boolean,
      required: true,
    },
  },
  data() {
    return {
      file: null,
      validTypes: [
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'application/vnd.ms-excel',
        'text/csv',
      ],
    }
  },
  methods: {
    handleFilesUpdated(files) {
      // * By default, only one file is received.
      this.file = files[0]
    },
  },
  watch: {
    file(newFile) {
      this.$emit('files-updated-stepper', newFile)
    },
  },
}
</script>

<style lang="scss" scoped>
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s;
}

.fade-enter,
.fade-leave-to {
  opacity: 0;
}
</style>
