<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapState, mapGetters } from 'vuex'

import STORE_INVENTORY_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import helpCategories from '@/config/helpCategories'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'
import helpCenterViewActions from '@/store/helpCenterView/actions.types'
import appActions from '@/store/app/actions.types'

import ToolBar from '@/components/shared/ToolBar'
import config from '@/components/ProductsView/ProductsToolbar/Operations/config'

export default {
  name: 'ProductsOperations',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
    }),
    ...mapState('products', ['data']),
    ...mapState('productsView', [
      'data',
      'filters',
      'component',
      'bulkDeletion',
    ]),
    ...mapGetters('account', ['getCountry']),
    ...mapGetters('helpCenter', ['getFilteredData']),
    componentConfig: function() {
      return config(
        {
          data: this.data,
          filters: this.filters,
          component: this.component,
          isScannerActive: this.isScannerActive,
          videos: this.getFilteredData,
          bulkDeletion: this.bulkDeletion,
        },
        {
          setSearchTerm: this[productsViewActions.setSearchTermFilter],
          updateScannerStatus: this[appActions.updateScannerStatus],
          setSelectedSuperCategories: this[
            productsViewActions.setSuperCategoriesFilter
          ],
          setViewType: this[productsViewActions.setViewType],
          onReset: this.onReset,
          resetScannerStatus: this.resetScannerStatus,
          setGroup: this[productsViewActions.setGroupFilter],
          downloadStoreInventory: this.downloadStoreInventory,
          importStoreInventory: this[
            productsViewActions.setImportProductsDialog
          ],
          changeBulkDeletionStatus: this.changeBulkDeletionStatus,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('productsView', [
      productsViewActions.setGroupFilter,
      productsViewActions.setSearchTermFilter,
      productsViewActions.setSuperCategoriesFilter,
      productsViewActions.setViewType,
      productsViewActions.setImportProductsDialog,
      productsViewActions.setBulkDeletionStatus,
    ]),
    ...mapActions('helpCenterView', [helpCenterViewActions.setVideoTypeFilter]),
    onReset: function() {
      this.$root.$emit('reset')
    },
    changeBulkDeletionStatus() {
      this.$root.$emit('bulkDeletionButtonWasClicked')
    },
    resetScannerStatus() {
      const searchInput = document.getElementById('product-input-search')
      this.isScannerActive ? searchInput.focus() : searchInput.blur()
      this[appActions.updateScannerStatus]()
    },
    downloadStoreInventory() {
      const downloadButton = document.getElementById('download-button-control')
      downloadButton.blur()
      rendererEventsService.send(STORE_INVENTORY_EVENTS.channel, {
        event: STORE_INVENTORY_EVENTS.events.download.name,
        data: { decimals: this.getCountry.decimals },
      })
      return
    },
  },
  mounted() {
    this[helpCenterViewActions.setVideoTypeFilter]([helpCategories.products])
  },
  beforeDestroy() {
    this[helpCenterViewActions.setVideoTypeFilter]([])
  },
}
</script>
