<template>
  <v-form
    ref="form"
    @submit.prevent="'onSubmit' in config ? config.onSubmit : null"
    :id="'id' in config ? config.id : ''"
  >
    <v-row>
      <template v-for="field in config.fields">
        <v-col
          v-if="Object.hasOwn(field, 'hideCol') ? !field.hideCol : true"
          :key="field.id"
          :cols="field.oneLine ? 12 : 6"
          :class="field.className ? field.className : 'pb-0 pt-1'"
        >
          <AccountInput
            :ref="field.id"
            v-if="field.type === 'account'"
            v-model="inputs[field.id]"
            :className="field.className"
            :v="config.state.v[field.id]"
            :label="field.label"
            :icon="field.icon"
            :readonly="field.readonly ? field.readonly : false"
            :autofocus="field.autofocus ? field.autofocus : false"
          />
          <PasswordInput
            :ref="field.id"
            v-if="field.type === 'password'"
            v-model="inputs[field.id]"
            :className="field.className"
            :v="config.state.v[field.id]"
            :label="field.label"
            :autofocus="field.autofocus ? field.autofocus : false"
          />
          <FormattedText
            v-if="field.type === 'formattedText'"
            :type="field.textType"
            :color="field.color"
            :class="field.class"
            :intl="field.intl"
            :value="field.value"
          />
          <CountryInputSelector
            :ref="field.id"
            v-if="field.type === 'countrySelector'"
            v-model="inputs[field.id]"
            :className="field.className"
            :v="config.state.v[field.id]"
          />
          <v-text-field
            v-if="isFieldVisible('input', field)"
            class="custom-text-field"
            v-model="inputs[field.id]"
            :type="field.valueType"
            :step="field.step ? field.step : 0.01"
            :label="getTranslatedText(field.label)"
            :placeholder="
              field.placeholder
                ? getTranslatedText(field.placeholder)
                : undefined
            "
            :color="field.color"
            filled
            rounded
            dense
            :readonly="field.readonly ? field.readonly : false"
            :error-messages="onValidateField(field.id)"
            :autofocus="field.autofocus ? field.autofocus : false"
            :prepend-inner-icon="field.prependIcon ? field.prependIcon : null"
            :suffix="field.suffix ? field.suffix : undefined"
            @input="
              field.id in config.state.v
                ? config.state.v[field.id].$reset()
                : null
            "
            @blur="
              field.id in config.state.v
                ? config.state.v[field.id].$touch()
                : null
            "
            @change="value => limitEmojis(value, field.id)"
            @focus="
              $event => ('onFocus' in field ? field.onFocus($event) : null)
            "
            @keydown.enter.prevent="
              $event => handleEnterKeyPress($event, field)
            "
          />
          <v-select
            v-if="field.type === 'select'"
            class="custom-text-field"
            v-model="inputs[field.id]"
            :items="field.items"
            :item-text="item => item[field.itemText ? field.itemText : 'text']"
            item-value="id"
            :label="getTranslatedText(field.label)"
            :color="field.color"
            filled
            rounded
            dense
            :error-messages="onValidateField(field.id)"
            :prepend-inner-icon="field.prependIcon ? field.prependIcon : null"
            @input="
              field.id in config.state.v
                ? config.state.v[field.id].$reset()
                : null
            "
            @blur="
              field.id in config.state.v
                ? config.state.v[field.id].$touch()
                : null
            "
            :ref="`selectInput-${field.id}`"
          />
          <v-checkbox
            :ref="field.id"
            v-if="field.type === 'checkbox'"
            v-model="inputs[field.id]"
            :label="getTranslatedText('starterLayout.signUp.privacy')"
            @click="field.onClick"
          ></v-checkbox>
          <v-radio-group
            v-if="field.type === 'radio'"
            v-model="inputs[field.id]"
            row
            :mandatory="false"
          >
            <span class="pr-6">
              <FormattedText :value="field.label" color="textPrimary" intl />
            </span>
            <div v-for="option in field.options" :key="option.label">
              <v-radio
                :label="getTranslatedText(option.label)"
                :value="option.value"
                :color="field.color"
              ></v-radio>
            </div>
          </v-radio-group>
          <v-file-input
            v-if="field.type === 'fileInput'"
            v-model="inputs[field.id]"
            class="custom-text-field"
            :accept="field.accept"
            :label="getTranslatedText(field.label)"
            :color="field.color"
            filled
            rounded
            dense
            :error-messages="onValidateField(field.id)"
            :prepend-icon="null"
            :append-icon="field.icon ? field.icon : null"
            @input="
              field.id in config.state.v
                ? config.state.v[field.id].$reset()
                : null
            "
            @blur="
              field.id in config.state.v
                ? config.state.v[field.id].$touch()
                : null
            "
          />
          <v-autocomplete
            v-if="field.type === 'autocomplete'"
            class="custom-text-field"
            v-model="inputs[field.id]"
            :items="field.items"
            :item-text="item => item[field.itemText ? field.itemText : 'text']"
            item-value="id"
            :label="getTranslatedText(field.label)"
            :color="field.color"
            filled
            rounded
            dense
            :placeholder="
              field.placeholder
                ? getTranslatedText(field.placeholder)
                : undefined
            "
            :readonly="field.readonly ? field.readonly : false"
            :error-messages="onValidateField(field.id)"
            :prepend-inner-icon="field.prependIcon ? field.prependIcon : null"
            @input="
              field.id in config.state.v
                ? config.state.v[field.id].$reset()
                : null
            "
            @blur="
              field.id in config.state.v
                ? config.state.v[field.id].$touch()
                : null
            "
          />
        </v-col>
      </template>
    </v-row>
  </v-form>
</template>

<script>
import { removeEmojis } from '@/tools/data'
import { validate } from '@/tools/validations'

import AccountInput from '@/components/shared/AccountInput'
import PasswordInput from '@/components/shared/PasswordInput'
import CountryInputSelector from '@/components/shared/CountryInputSelector'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'Form2Columns',
  components: {
    AccountInput,
    PasswordInput,
    CountryInputSelector,
    FormattedText,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  computed: {
    inputs() {
      return this.config.state.inputs
    },
    errorMessages() {
      let messages = {}
      this.config.fields.forEach(
        field => (messages[field.id] = field.errorMessage)
      )
      return messages
    },
  },
  methods: {
    getTranslatedText: function(translateString) {
      return this.$vuetify.lang.t(`$vuetify.${translateString}`)
    },
    limitEmojis(value, fieldId) {
      this.inputs[fieldId] = removeEmojis(value.toString())
    },
    onValidateField(idInput) {
      return validate(this.config.state.v, idInput, {
        fn: this.getTranslatedText,
        message: this.errorMessages[idInput],
      })
    },
    isFieldVisible(inputType, field) {
      const isVisible = Object.hasOwn(field, 'visible') ? field.visible : true
      return field.type === inputType && isVisible
    },
    handleEnterKeyPress($event, field) {
      if ($event.key === 'Enter' && 'onEnterKey' in field) {
        field.onEnterKey($event)
      }
    },
  },
}
</script>
