<template>
  <v-dialog
    v-model="importProductsDialog.isOpen"
    max-width="750px"
    :overlay-opacity="0.15"
    @click:outside="onClickCancel"
  >
    <v-card flat color="cardBackgroundPrimary" height="670">
      <v-card-title>
        <FormattedText intl value="productsView.importProductsDialog.title" />
      </v-card-title>
      <v-row no-gutters>
        <v-col cols="12">
          <ImportStepper />
        </v-col>
      </v-row>
    </v-card>
  </v-dialog>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import productsViewActions from '@/store/productsView/action.types'

import FormattedText from '@/components/shared/FormattedText'
import ImportStepper from '@/components/ProductsView/ImportStoreInventoryDialog/ImportStepper'

export default {
  name: 'ImportStoreInventoryDialog',
  components: { FormattedText, ImportStepper },
  computed: {
    ...mapState('productsView', ['importProductsDialog']),
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setImportProductsDialog,
    ]),
    onClickCancel() {
      this[productsViewActions.setImportProductsDialog](false)
    },
  },
}
</script>
