<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'
import salesActions from '@/store/sales/actions.types'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import setDialogConfig from '@/components/ProductDetail/Footer/ProductInSaleDialog/config'

import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'ProductInSaleDialog',
  components: { DialogCard },
  computed: {
    ...mapState('productsView', ['productInSaleDialog']),
    ...mapState('sales', ['sales']),
    ...getSelectedProductByRoute(),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.productInSaleDialog.isOpen,
          routeName: this.$route.name,
        },
        {
          closeDialog: this.closeDialog,
          confirmDialog: this.confirmDialog,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setProductInSaleDialogStatus,
      productsViewActions.setDeleteProductDialogStatus,
    ]),
    ...mapActions('sales', [salesActions.removeProductFromAllSales]),
    closeDialog() {
      this[productsViewActions.setProductInSaleDialogStatus](false)
      this[productsViewActions.setDeleteProductDialogStatus](false)
    },
    async confirmDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ProductInSaleDialog',
        name: 'Confirm',
      })
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.removeItemInDraftPurchases.name,
        data: { productsId: [this.selectedProduct.id] },
      })
    },
  },
  beforeMount() {
    this.$root.$on('productDetailTabsWasChanged', this.closeDialog)
  },
  beforeDestroy() {
    this[productsViewActions.setProductInSaleDialogStatus](false)
    this.$root.$off('productDetailTabsWasChanged', this.closeDialog)
  },
}
</script>
