const config = (state, methods) => ({
  state,
  methods,
  groups: [
    {
      id: 'operations-group-01',
      controls: [
        {
          id: 'help-dropdown-control',
          type: 'buttonDropdown',
          label: 'productsView.toolbar.buttons.help',
          icon: 'mdi-school',
          color: 'help',
          textColor: 'textPrimary',
          items: state.videos,
          listItemType: 'VideoListItem',
        },
        {
          id: 'upload-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.upload',
          icon: 'mdi-upload',
          color: 'accent',
          onClick: () => methods.importStoreInventory(true),
        },
        {
          id: 'download-button-control',
          type: 'button',
          label: 'productsView.toolbar.buttons.download',
          icon: 'mdi-download',
          color: 'accent',
          onClick: () => methods.downloadStoreInventory(),
        },
        {
          id: 'scan-button-control',
          type: 'button',
          label:
            state.isScannerActive === true
              ? 'productsView.toolbar.buttons.keyboard'
              : 'productsView.toolbar.buttons.scan',
          icon:
            state.isScannerActive === true
              ? 'mdi-keyboard-outline'
              : 'mdi-barcode-scan',
          color: 'accent',
          context: true,
          onClick: () => {
            methods.onReset()
            methods.setSelectedSuperCategories([])
            methods.setSearchTerm(null)
            methods.setGroup(state.isScannerActive === true ? 'search' : 'all')
            methods.resetScannerStatus()
          },
        },
        {
          id: 'list-type-control',
          type: 'button',
          label:
            state.component !== 'PaginatedCards'
              ? 'productsView.toolbar.buttons.cardsViewType'
              : 'productsView.toolbar.buttons.tableViewType',
          icon:
            state.component !== 'PaginatedCards'
              ? 'mdi-card-bulleted'
              : 'mdi-table',
          color: 'accent',
          onClick: () => {
            state.component !== 'PaginatedCards'
              ? methods.setViewType('PaginatedCards')
              : methods.setViewType('PaginatedTable')
          },
        },
        {
          id: 'bulk-deletion-control',
          type: 'button',
          label: state.bulkDeletion.isActive
            ? 'productsView.toolbar.buttons.bulkDeletionDisabled'
            : 'productsView.toolbar.buttons.bulkDeletionEnabled',
          icon: 'mdi-delete',
          color: state.bulkDeletion.isActive ? 'error' : 'accent',
          onClick: () => methods.changeBulkDeletionStatus(),
        },
      ],
    },
  ],
})

export default config
