import light from '@/themes/light'
import dark from '@/themes/dark'

export const config = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: () => null,
    onDblClick: () => null,
  },
  hideTop: true,
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  page: 1,
  rowsPerPage: 6,
  rowOffsetHeight: 48,
  itemsPerRow: {
    withoutDetail: {
      lg: 3,
      xl: 4,
    },
  },
  headers: [
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.importProductsDialog.stepper.steps.step3.table.upcCode'
      ),
      align: 'start',
      value: 'upc',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.importProductsDialog.stepper.steps.step3.table.name'
      ),
      value: 'name',
      format: item => item,
    },
    {
      text: methods.context.$vuetify.lang.t(
        '$vuetify.productsView.importProductsDialog.stepper.steps.step3.table.error'
      ),
      value: 'error',
      format: item => methods.getTranslatedText(item),
    },
  ],
})

export default config
