<template>
  <v-stepper v-model="currentStep" class="stepper">
    <v-stepper-header class="stepper__header">
      <template v-for="step in steps">
        <v-stepper-step
          :key="step.id"
          :step="step.step"
          :editable="step.editable"
          :complete="step.complete"
        >
          <FormattedText intl :value="step.name" />
        </v-stepper-step>
      </template>
    </v-stepper-header>
    <v-stepper-items>
      <v-stepper-content v-for="step in steps" :key="step.id" :step="step.step">
        <component
          :is="step.component"
          class="component-step"
          @files-updated-stepper="handleFilesUpdated"
          :isLoading="isImport"
        />
        <div class="pt-12">
          <div class="d-flex justify-space-between my-4">
            <div>
              <CustomButton
                className="mx-2"
                color="accent"
                text="shared.cancel"
                intl
                textType="text-button"
                @click="closeDialog"
                :disabled="isImport"
                v-if="showCancelButton"
              />
            </div>
            <div class="d-flex justify-end ">
              <transition name="fade">
                <CustomButton
                  className="mx-2"
                  color="accent"
                  text="shared.previous"
                  intl
                  textType="text-button"
                  @click="previousStep"
                  v-if="showPreviousButton"
                />
              </transition>
              <CustomButton
                :text="continueButtonText"
                intl
                textType="text-button"
                @click="nextStep"
                :disabled="isNexStepButtonDisable"
                :isLoading="isImport"
              />
            </div>
          </div>
        </div>
      </v-stepper-content>
    </v-stepper-items>
  </v-stepper>
</template>

<script>
import fs from 'fs'
import { isNil } from 'ramda'
import { mapActions, mapGetters } from 'vuex'

import STORE_INVENTORY_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'
import appActions from '@/store/app/actions.types'

import { steps } from '@/components/ProductsView/ImportStoreInventoryDialog/ImportStepper/stepperConfig'
import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'

export default {
  name: 'ImportStepper',
  components: { FormattedText, CustomButton },
  data() {
    return {
      currentStep: 1,
      steps: steps,
      file: null,
      importResult: null,
      isImport: false,
    }
  },
  computed: {
    ...mapGetters('account', ['getCountry']),
    continueButtonText() {
      let text = ''
      switch (this.currentStep) {
        case 2:
          text = 'productsView.importProductsDialog.stepper.steps.step2.button'
          break
        case 3:
          text = 'shared.finish'
          break
        default:
          text = 'shared.continue'
          break
      }
      return text
    },
    showPreviousButton() {
      return this.currentStep === 2 && !this.isImport
    },
    showCancelButton() {
      return !(this.currentStep === this.steps.length)
    },
    isNexStepButtonDisable() {
      return (this.currentStep === 2 && isNil(this.file)) || this.isImport
    },
  },
  methods: {
    ...mapActions('products', [
      productsActions.addProductFromMLP,
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.removeProductFromMlpData,
      productsActions.updateProductByProperties,
      productsActions.updateByWeightTree,
      productsActions.updateSimilarProduct,
    ]),
    ...mapActions('productsView', [
      productsViewActions.setImportProductsDialog,
    ]),
    ...mapActions('app', [appActions.addPendingSyncOperation]),
    handleFilesUpdated(file) {
      this.file = file
    },
    closeDialog() {
      this[productsViewActions.setImportProductsDialog](false)
    },
    previousStep() {
      if (this.currentStep === 1) return
      this.currentStep -= 1
    },
    nextStep() {
      if (this.currentStep === this.steps.length) {
        this[productsViewActions.setImportProductsDialog](false)
        return
      }
      if (this.currentStep === 2) {
        const fileSerialize = fs.readFileSync(this.file.path)
        this[productsActions.setProductsOrSuperCategoriesFetching](true)
        this.isImport = true
        rendererEventsService.send(STORE_INVENTORY_EVENTS.channel, {
          event: STORE_INVENTORY_EVENTS.events.import.name,
          data: {
            file:
              this.file.type === 'text/csv'
                ? fileSerialize.toString()
                : fileSerialize,
            type: this.file.type,
            country: {
              countryTag: this.getCountry.countryTag,
              decimals: this.getCountry.decimals,
            },
          },
        })
        return
      }
      this.currentStep += 1
    },
    onProductsAdded(data) {
      const { productsImported, productsUpdated } = data
      productsImported.forEach(product => {
        this[productsActions.addProductFromMLP]({
          newProduct: product,
          fromImportInventory: true,
        })
        this[productsActions.updateByWeightTree]({
          upc: product.upc_code,
          isGramaje: product.is_gramaje,
        })
        this[productsActions.removeProductFromMlpData](product)
      })
      productsUpdated.forEach(product => {
        this[productsActions.updateProductByProperties](product)
        this[productsActions.updateByWeightTree]({
          upc: product.upc_code,
          isGramaje: product.is_gramaje,
        })
      })
      this[productsActions.updateSimilarProduct]()
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      this.currentStep = 3
    },
    async storeInventoryListiner(event, payload) {
      const events = STORE_INVENTORY_EVENTS.events
      const replies = {
        [events.import.replies.success]: () => {
          this.importResult = payload.data
          this.onProductsAdded(payload.data)
          this.steps[1].complete = true
          this.isImport = false
          this[appActions.addPendingSyncOperation]()
        },
        [events.import.replies.error]: () => {
          this.isImport = false
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
          this[productsViewActions.setImportProductsDialog](false)
          notificationsService.showError(
            'notification.products.errorImport',
            this.$vuetify.lang
          )
        },
        [events.downloadTemplate.replies.success]: () => {
          notificationsService.showOpenFolder(
            payload.data.filePath,
            'shared.fileDownloaded',
            this.$vuetify.lang,
            {
              timeout: 8000,
            }
          )
        },
        [events.downloadTemplate.replies.error]: () =>
          notificationsService.showError(
            'notification.products.errorTemplateDownload',
            this.$vuetify.lang
          ),
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.storeInventoryListiner
    )
  },
  beforeDestroy() {
    this.steps[1].complete = false
    rendererEventsService.removeListener(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.storeInventoryListiner
    )
  },
}
</script>

<style lang="scss" scoped>
.stepper {
  box-shadow: none !important;
  .stepper__header {
    box-shadow: none !important;
  }
  .component-step {
    height: 370px;
  }
}
.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s;
}

.fade-enter,
.fade-leave-to {
  opacity: 0;
}
</style>
