<template>
  <v-card-actions id="product-detail-card-footer">
    <div>
      <v-btn
        v-if="showDeleteButton"
        color="error"
        @click="openDeleteProductDialog"
        ref="productDetailDeleteButton"
        v-track:click="{
          category: $route.name,
          screen: 'ProductDetails',
          name: 'Delete product',
        }"
      >
        <v-icon color="white">mdi-delete-outline</v-icon>
        <FormattedText intl value="productsView.details.delete" color="white" />
      </v-btn>
      <DeleteProductDialog v-if="deleteProductDialog.isOpen" />
      <ProductInSaleDialog v-if="productInSaleDialog.isOpen" />
      <v-btn
        color="accent"
        class="px-2 action-button"
        @click="openReportDialog"
        ref="productDetailReportButton"
        v-track:click="{
          category: $route.name,
          screen: 'ProductDetails',
          name: 'Report error',
        }"
      >
        <v-icon color="white">mdi-alert-circle-outline</v-icon>
        <FormattedText intl value="productsView.details.report" color="white" />
      </v-btn>
      <ReportDialog v-if="reportDialog.isOpen" :product="selectedProduct" />
      <WastedProducts />
    </div>
    <div>
      <v-btn
        id="product-detail-close-button"
        color="accent"
        @click="onClickClose"
        ref="productDetailCloseButton"
        v-track:click="{
          category: $route.name,
          screen: 'ProductDetails',
          name: 'Close product details',
        }"
      >
        <v-icon>mdi-close-circle-outline</v-icon>
        <FormattedText intl value="productsView.details.close" color="white" />
      </v-btn>
    </div>
  </v-card-actions>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getActionsTypes, getViewStore } from '@/tools/view'

import productsViewActions from '@/store/productsView/action.types'

import {
  getSelectedProductByRoute,
  updateSelectedProductByRoute,
} from '@/components/ProductDetail/selectedProduct.tools'

import FormattedText from '@/components/shared/FormattedText'
import ReportDialog from '@/components/ProductDetail/Footer/ReportDialog'
import DeleteProductDialog from '@/components/ProductDetail/Footer/DeleteProductDialog'
import ProductInSaleDialog from '@/components/ProductDetail/Footer/ProductInSaleDialog'
import WastedProducts from '@/components/ProductDetail/Footer/WastedProducts'

export default {
  name: 'Footer',
  components: {
    WastedProducts,
    FormattedText,
    ReportDialog,
    DeleteProductDialog,
    ProductInSaleDialog,
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState({
      searchTerm(state) {
        return state[getViewStore(this.$route.name)].filters.searchTerm
      },
      superCategories(state) {
        return state[getViewStore(this.$route.name)].filters.superCategories
      },
    }),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('productsView', [
      'deleteProductDialog',
      'productInSaleDialog',
      'reportDialog',
    ]),
    ...getSelectedProductByRoute(),
    showDeleteButton() {
      return (
        this.selectedUser.id === 1 ||
        this.selectedUser.inventoryPermission === 0
      )
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setDeleteProductDialogStatus,
      productsViewActions.setReportDialogStatus,
    ]),
    ...mapActions({
      toggleDetailDialog(dispatch) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).toggleDetailDialog
          }`
        )
      },
      setSearchTermFilter(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setSearchTermFilter
          }`,
          payload
        )
      },
      setGroupFilter(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setGroupFilter
          }`,
          payload
        )
      },
      setSuperCategoriesFilter(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setSuperCategoriesFilter
          }`,
          payload
        )
      },
    }),
    ...updateSelectedProductByRoute(),
    onClickClose() {
      this.toggleDetailDialog()
      this.setSelectedProduct(null)
      this.setGroupFilter(this.defaultProductsFilter)
      this.setSuperCategoriesFilter([])
      document.getElementById('clear-button-control').click()
      if (this.isScannerActive === true) this.setSearchTermFilter(null)
    },
    openDeleteProductDialog() {
      this[productsViewActions.setDeleteProductDialogStatus](true)
    },
    openReportDialog() {
      this[productsViewActions.setReportDialogStatus](true)
    },
  },
}
</script>
