<template>
  <div class="fill-height px-3">
    <PaginatedList :config="tableComponentConfig">
      <template v-slot:headerLeft>
        <DownloadHomeCodes />
      </template>
    </PaginatedList>
    <v-dialog
      v-model="productDetailDialog.isOpen"
      max-width="715"
      :overlay-opacity="0.15"
      content-class="default-dialog"
      @click:outside="onClickOutside"
      @keydown.esc="onClickOutside"
    >
      <!-- Detail view -->
      <ProductDetail v-if="productDetailDialog.isOpen" />
    </v-dialog>
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'
import { isNil, concat } from 'ramda'

import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'

import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'
import productsActions from '@/store/products/actions.types'
import appActions from '@/store/app/actions.types'

import PaginatedList from '@/components/shared/PaginatedTable'
import ProductDetail from '@/components/ProductDetail'
import setConfig from '@/components/ProductsView/ProductsList/PaginatedTable/config'
import DownloadHomeCodes from '@/components/ProductsView/ProductsList/DownloadHomeCodes'

export default {
  name: 'PaginatedTableList',
  components: {
    DownloadHomeCodes,
    PaginatedList,
    ProductDetail,
  },
  props: {
    bulkDeletionConfig: {
      type: Object,
      default: null,
    },
  },
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
    }),
    ...mapState('products', ['data', 'fetching']),
    ...mapState('productsView', ['filters']),
    ...mapState('app', ['windowSize']),
    ...mapState({
      productDetailDialog(state) {
        return state[this.getViewStore()].productDetailDialog
      },
    }),
    ...mapGetters('products', ['getFilteredData']),
    filteredData() {
      const searchTerm = this.filters.searchTerm
      if (
        !isNil(searchTerm) &&
        this.isScannerActive === true &&
        this.getFilteredData.length === 0
      )
        this.tryAddProductFromMLP(searchTerm)
      return concat(this.getFilteredData, this.data.mlp)
    },
    tableComponentConfig() {
      return setConfig(
        {
          items: this.filteredData,
          windowHeight: this.windowSize.y,
          fetching: this.fetching,
          filters: this.filters,
          bulkDeletion: this.bulkDeletionConfig,
        },
        {
          onClickRow: this.onClickRow,
          toggleDetailPanel: this[productsViewActions.toggleDetailDialog],
          context: this,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('products', [
      productsActions.setProductsOrSuperCategoriesFetching,
    ]),
    ...mapActions('productsView', [
      productsViewActions.toggleDetailDialog,
      productsViewActions.setSelectedProduct,
      productsViewActions.setSearchTermFilter,
    ]),
    getViewStore() {
      return this.$route.name === 'Products' ? 'productsView' : 'salesView'
    },
    onClickOutside() {
      this[productsViewActions.toggleDetailDialog]()
      this[productsViewActions.setSelectedProduct](null)
      if (this.isScannerActive === true)
        this[productsViewActions.setSearchTermFilter](null)
    },
    tryAddProductFromMLP(searchTerm) {
      if (this.fetching) return
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: { item: { property: 'upc_code', value: searchTerm, limit: 1 } },
      })
    },
    onClickRow(item) {
      if (this.bulkDeletionConfig && this.bulkDeletionConfig.isActive) {
        if (!('storeId' in item)) return
        this.bulkDeletionConfig.itemToBeDelete(item.id)
        return
      }
      if (isNil(item.isStoreInventory) || item.isStoreInventory === 1) {
        this[productsViewActions.setSelectedProduct](item)
        this[productsViewActions.toggleDetailDialog]()
        return
      }
      this.tryAddProductFromMLP(item.upc)
    },
  },
}
</script>
