<template>
  <v-card
    id="product-detail-card"
    flat
    class="view-section"
    :class="{ collapsed: productDetailDialog.isOpen }"
    :height="panelSize"
    color="cardBackgroundPrimary"
  >
    <div v-if="selectedProduct">
      <Header />
      <v-card-text>
        <Tabs
          :tabs="tabs"
          backgroundColor="cardBackgroundPrimary"
          textColor="cardPrimary"
          class="fill-height"
          track-screen="ProductDetails"
          @change="$root.$emit('productDetailTabsWasChanged')"
        />
      </v-card-text>
      <Footer />
    </div>
    <ChangeOpenGramajeDialog v-if="changeOpenGramajeDialog.isOpen" />
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import SYNCHRONIZATION_EVENTS from '@/config/events/synchronization'
import STOCK_MODIFICATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/stockModificationsEvents'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import { storeInventory as storeInventoryMapper } from '@/config/storeMapper'

import { getActionsTypes, getViewStore } from '@/tools/view'
import { getTranslatedText, mapStoreObject } from '@/tools/data'
import { captureException } from '@/tools/exceptions'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'
import purchasesViewActions from '@/store/purchasesView/actions.types'
import salesActions from '@/store/sales/actions.types'

import {
  getSelectedProductByRoute,
  isOpenGramaje,
} from '@/components/ProductDetail/selectedProduct.tools'
import Header from '@/components/ProductDetail/Header'
import Tabs from '@/components/shared/Tabs'
import DetailsTab from '@/components/ProductDetail/DetailsTab'
import SalesTab from '@/components/ProductDetail/SalesTab'
import PurchasesTab from '@/components/ProductDetail/PurchasesTab'
import HistoryTab from '@/components/ProductDetail/HistoryTab'
import Footer from '@/components/ProductDetail/Footer'
import ChangeOpenGramajeDialog from '@/components/ProductDetail/ChangeOpenGramajeDialog'
import {
  getPackagesStockValue,
  getPiecesStockValue,
} from '@/components/ProductDetail/DetailsTab/tools'

export default {
  name: 'ProductDetail',
  components: {
    Header,
    Tabs,
    Footer,
    ChangeOpenGramajeDialog,
  },
  data() {
    return {
      deletingProduct: false,
      tabs: [
        {
          id: 0,
          name: this.getTranslatedText(
            'productsView.details.tabs.details.name'
          ),
          icon: 'mdi-clipboard-check',
          component: DetailsTab,
        },
        {
          id: 1,
          name: this.getTranslatedText(
            'productsView.details.tabs.purchases.name'
          ),
          icon: 'mdi-truck',
          component: PurchasesTab,
        },
        {
          id: 2,
          name: this.getTranslatedText('productsView.details.tabs.sales.name'),
          icon: 'mdi-cart',
          component: SalesTab,
        },
        {
          id: 3,
          name: this.getTranslatedText(
            'productsView.details.tabs.history.name'
          ),
          icon: 'mdi-history',
          component: HistoryTab,
        },
      ],
    }
  },
  computed: {
    ...mapState('products', ['data']),
    ...mapState('productsView', ['changeOpenGramajeDialog']),
    ...mapState({
      group(state) {
        return state[getViewStore(this.$route.name)].filters.group
      },
    }),
    ...mapState({
      productDetailDialog(state) {
        return state[getViewStore(this.$route.name)].productDetailDialog
      },
    }),
    ...mapState('sales', ['sales']),
    ...mapState('app', ['windowSize']),
    ...getSelectedProductByRoute(),
    currentView() {
      return getViewStore(this.$route.name)
    },
    panelSize() {
      return this.windowSize.y > 935 ? 880 : 770
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('products', [
      productsActions.editProductField,
      productsActions.removeProduct,
      productsActions.updateByWeightTree,
    ]),
    ...mapActions('productsView', [
      productsViewActions.setDeleteProductDialogStatus,
    ]),
    ...mapActions('sales', [salesActions.removeProductFromAllSales]),
    ...mapActions('purchasesView', [
      purchasesViewActions.removeProductFromPurchase,
      purchasesViewActions.removeReturnProductFromPurchase,
    ]),
    ...mapActions({
      toggleDetailDialog(dispatch) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).toggleDetailDialog
          }`
        )
      },
      setSearchTermFilter(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setSearchTermFilter
          }`,
          payload
        )
      },
      setSelectedProduct(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setSelectedProduct
          }`,
          payload
        )
      },
      setGroupFilter(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).setGroupFilter
          }`,
          payload
        )
      },
    }),
    onChangeUnitMeasure(product) {
      this.setSelectedProduct(product)
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.removeItemInDraftPurchases.name,
        data: {
          productsId: [product.id],
          isChangeUnitMeasure: true,
        },
      })
      this.$root.$emit('sendOpsToSync')
    },
    async storeInventoryListener(event, payload) {
      const storeInventoryEvents = STORE_INVENTORY_DB_API_EVENTS.events
      const replies = {
        [storeInventoryEvents.updateById.replies.success]: async () => {
          await this[productsActions.editProductField](payload.data)
          this.$root.$emit('productStoreWasUpdated')
          this.$root.$emit('productWasEdited', payload.data._id)
          if (payload.extras.isUnitMeasureChange) {
            let product = mapStoreObject(payload.data, storeInventoryMapper)
            product['isStoreInventory'] = 1
            product['isOpenGramaje'] = isOpenGramaje(product)
            if (product.factor > 1) {
              const { quantity, factor } = product
              product['piecesQuantity'] = getPiecesStockValue(quantity, factor)
              product['packagesQuantity'] = getPackagesStockValue(
                quantity,
                factor
              )
            }
            this.onChangeUnitMeasure(product)
          }
        },
        [storeInventoryEvents.generateWastedProducts.replies
          .success]: async () => {
          await this[productsActions.editProductField](payload.data)
          this.$root.$emit('productStoreWasUpdated', 'generateWastedProducts')
          this.$root.$emit('productWasEdited', payload.data._id)
        },
        [storeInventoryEvents.delete.replies.success]: () => {
          rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
            event: SYNCHRONIZATION_EVENTS.events.deleteOperation.name,
            data: {
              entityData: payload.data,
              entityName: 'stock',
            },
          })
          this[productsActions.removeProduct](payload.data)
          this.deletingProduct = false
          notificationsService.showSuccess(
            'notification.products.deleted',
            this.$vuetify.lang
          )
          this.$root.$emit('productWasDeleted', { productId: payload.data })
          this[productsViewActions.setDeleteProductDialogStatus](false)
          this.toggleDetailDialog()
        },
        [storeInventoryEvents.delete.replies.error]: () => {
          this.deletingProduct = false
          if (payload.data) captureException(payload.data)
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    stockModificationsListener(event, payload) {
      const replies = {
        [STOCK_MODIFICATIONS_DB_API_EVENTS.events.delete.replies
          .success]: async () => {
          rendererEventsService.send(SYNCHRONIZATION_EVENTS.channel, {
            event: SYNCHRONIZATION_EVENTS.events.createOperation.name,
            data: {
              entityData: JSON.parse(JSON.stringify(payload.data.product)),
              entityName: 'stock',
              extras: 'extras' in payload ? payload.extras : null,
            },
          })
          await this[productsActions.editProductField](payload.data.product)
          this.$root.$emit('productStoreWasUpdated', 'deleteStockModification')
          this.$root.$emit('productWasEdited', payload.data._id)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async purchaseOrderListener(event, payload) {
      const purchaseEvents = PURCHASES_DB_API_EVENTS.events
      const replies = {
        [purchaseEvents.removeItemInDraftPurchases.replies.success]: () => {
          this[salesActions.removeProductFromAllSales]({
            product: this.selectedProduct,
          })
          this[purchasesViewActions.removeProductFromPurchase]({
            upcProduct: this.selectedProduct.upc,
          })
          this[purchasesViewActions.removeReturnProductFromPurchase]({
            returnProductId: this.selectedProduct.id,
          })
          if (payload.data.isChangeUnitMeasure) {
            this[productsActions.updateByWeightTree]({
              upc: this.selectedProduct.upc,
              isGramaje: this.selectedProduct.isGramaje,
            })
            this.$root.$emit('productChangedUnitMeasure', {
              productId: this.selectedProduct.id,
              fromChangeMeasure: true,
            })
          } else {
            this.deleteProduct()
          }
        },
        [purchaseEvents.removeItemInDraftPurchases.replies.error]: () => {
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    deleteProduct() {
      if (this.deletingProduct) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'DeleteProductDialog',
        name: `Confirm delete product`,
      })
      this.deletingProduct = true
      this.setSearchTermFilter(null)
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.delete.name,
        data: { productId: this.selectedProduct.id },
      })
      this.group === 'all'
        ? this.setGroupFilter('all')
        : this.setGroupFilter(this.group)
    },
  },
  mounted() {
    if (testMode) return
    this.$root.$on('productMustBeDeleted', this.deleteProduct)
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.storeInventoryListener
    )
    rendererEventsService.subscribe(
      STOCK_MODIFICATIONS_DB_API_EVENTS.replyChannel,
      this.stockModificationsListener
    )
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
  beforeDestroy() {
    this.$root.$off('productMustBeDeleted', this.deleteProduct)
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.storeInventoryListener
    )
    rendererEventsService.removeListener(
      STOCK_MODIFICATIONS_DB_API_EVENTS.replyChannel,
      this.stockModificationsListener
    )
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
}
</script>

<style lang="scss" scoped>
.view-section {
  > div {
    display: contents;
  }
}
</style>
