const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-alert-circle',
    title: 'productsView.changeOpenGramajeDialog.title',
    titleColor: 'textPrimary',
    maxWidth: 500,
    persistent: true,
    isAcceptButtonDisabled: state.formInvalid,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.changeInventory(),
  },
})

export default setConfig
