<template>
  <v-container fluid class="products-view" id="products-view">
    <!-- View toolbar  -->
    <v-row no-gutters>
      <v-col
        class="products-view__filter-toolbar pl-6 pr-3 pt-6"
        id="products-view__filter-toolbar"
      >
        <MainToolBar />
      </v-col>
    </v-row>
    <!-- List view -->
    <v-row no-gutters>
      <v-col
        cols="12"
        class="products-view__products-list"
        id="products-view__products-list"
        :style="{
          height: `calc(100vh - ${getProductListStyles}px)`,
        }"
      >
        <ProductsList />
      </v-col>
      <v-col cols="12">
        <BulkDeletion class="mt-n11" />
      </v-col>
    </v-row>
    <AddNewProductDialog v-if="newProductDialog.isOpen === true" />
    <ProductsViewTour v-if="selectedUser.productsTourDisabled === 0" />
    <ImportStoreInventoryDialog v-if="importProductsDialog.isOpen" />
  </v-container>
</template>

<script>
import { mapActions, mapState, mapGetters } from 'vuex'

import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'
import STORE_INVENTORY_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'
import productsActions from '@/store/products/actions.types'
import appActions from '@/store/app/actions.types'

import MainToolBar from '@/components/ProductsView/ProductsToolbar'
import ProductsList from '@/components/ProductsView/ProductsList'
import ProductsViewTour from '@/components/ProductsView/ProductsViewTour'
import AddNewProductDialog from '@/components/AddNewProductDialog'
import ImportStoreInventoryDialog from '@/components/ProductsView/ImportStoreInventoryDialog'
import BulkDeletion from '@/components/ProductsView/ProductsList/BulkDeletion'

export default {
  name: 'Products',
  components: {
    BulkDeletion,
    MainToolBar,
    ProductsList,
    ProductsViewTour,
    AddNewProductDialog,
    ImportStoreInventoryDialog,
  },
  data() {
    return {
      layoutCommonElementsHeight: 0,
    }
  },
  searchInput: null,
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('products', ['data']),
    ...mapState('productsView', [
      'newProductDialog',
      'productDetailDialog',
      'filters',
      'importProductsDialog',
      'tourEnabled',
    ]),
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('products', ['getFilteredData']),
    getProductListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('products', [
      productsActions.fetchProducts,
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.setProductsOrSuperCategoriesError,
      productsActions.addProductFromMLP,
      productsActions.setMlpFilteredProducts,
      productsActions.removeProductFromMlpData,
    ]),
    ...mapActions('productsView', [
      productsViewActions.setGroupFilter,
      productsViewActions.setSearchTermFilter,
      productsViewActions.setSuperCategoriesFilter,
      productsViewActions.setSelectedProduct,
      productsViewActions.toggleDetailDialog,
      productsViewActions.toggleAddProductDialog,
      productsViewActions.setProductsTourEnabled,
    ]),
    entitiesListener(event, payload) {
      const replies = {
        [ENTITIES_EVENTS.events.getAllByEntities.replies.success.concat(
          '-fetchProducts'
        )]: async () => {
          await this[productsActions.fetchProducts](payload.data)
          this.getLayoutHeight()
        },
        [ENTITIES_EVENTS.events.getAllByEntities.replies.error]: () => {
          this[productsActions.setProductsOrSuperCategoriesError](payload.data)
          this[productsActions.setProductsOrSuperCategoriesFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    addProductListener(event, payload) {
      const events = ADD_PRODUCT_EVENTS.events
      const replies = {
        [events.addProductFromMLP.replies.success]: () =>
          this.onProductAddedFromMLP(payload.data),
        [events.addProductFromMLP.replies.error]: () =>
          this.onAddingProductFromMLPError(payload.data),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    mlpApiListener(event, payload) {
      const replies = {
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies
          .success]: () => {
          this[productsActions.setMlpFilteredProducts](payload.data)
        },
        [MLP_DB_API_EVENTS.events.findByPropertiesLikes.replies.error]: () => {
          notificationsService.showError(payload.error, this.$vuetify.lang, {
            timeout: 8000,
          })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    downloadStoreInventoryListener(event, payload) {
      const replies = {
        [STORE_INVENTORY_EVENTS.events.download.replies.error]: () => {
          notificationsService.showError(
            'productsView.listView.messages.downloadError',
            this.$vuetify.lang
          )
        },
        [STORE_INVENTORY_EVENTS.events.download.replies.success]: () => {
          notificationsService.showOpenFolder(
            payload.data.filePath,
            'productsView.listView.messages.downloadSuccess',
            this.$vuetify.lang,
            {
              timeout: 8000,
            }
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'products-view'
      )
      const productViewToolbar = document.getElementById(
        'products-view__filter-toolbar'
      ).offsetHeight

      this.layoutCommonElementsHeight =
        layoutComponentsHeight + productViewToolbar
    },
    onBarcodeScanned(barcode) {
      this.$track({
        type: 'interaction',
        action: 'scan',
        category: 'Products',
        screen: 'ProductsList',
        name: `Product scanned`,
      })
      if (this.tourEnabled) {
        this.$root.$emit('product-scanned-products-tour', barcode.trim())
        return
      }
      this.$root.$emit('reset')
      this[productsViewActions.setSuperCategoriesFilter]([])
      this[productsViewActions.setSearchTermFilter](barcode)
      if (this.filters.group !== 'search' && this.getFilteredData.length > 1) {
        this[productsViewActions.setSearchTermFilter](null)
        this.$root.$emit('reset')
      }
      if (this.productDetailDialog.isOpen === true)
        this[productsViewActions.toggleDetailDialog]()
      if (!this.isScannerActive) {
        this.searchInput.blur()
        this[appActions.updateScannerStatus]()
      }
      if (this.getFilteredData.length === 1) {
        this.$track({
          type: 'system',
          action: 'scan',
          category: 'Products',
          screen: 'ProductsList',
          name: `Open product details`,
        })
        this[productsViewActions.toggleDetailDialog]()
        this[productsViewActions.setSelectedProduct](this.getFilteredData[0])
      }
      if (this.filters.group === 'search') {
        this[productsViewActions.setGroupFilter]('all')
      }
    },
    onProductAddedFromMLP(data) {
      this.$track({
        type: 'system',
        action: 'add_product_mlp',
        category: 'Products',
        screen: 'ProductsList',
        name: `Open product details`,
      })
      this[productsActions.addProductFromMLP]({
        newProduct: data.newProduct,
        currentView: 'productsView',
      })
      this[productsActions.setProductsOrSuperCategoriesFetching](false)
      this[productsActions.removeProductFromMlpData](data.newProduct)
      notificationsService.showInfo(
        'productsView.listView.messages.newProductAdded',
        this.$vuetify.lang,
        { timeout: 8000 }
      )
    },
    onAddingProductFromMLPError(data) {
      if (data.error.message === 'newProduct') {
        this.$track({
          type: 'system',
          action: 'add_product_mlp',
          category: 'Products',
          screen: 'ProductsList',
          name: `Show add custom product dialog`,
        })
        this[productsViewActions.toggleAddProductDialog]()
        return
      }
      notificationsService.showError(data.errorMsg, this.$vuetify.lang, {
        timeout: 8000,
      })
      this.$root.$emit('reset')
      this.resetScannerStatus(this.defaultProductsFilter)
      this[productsViewActions.setSearchTermFilter](null)
      if (data.error.message === 'invalid-barcode') {
        this[productsActions.setProductsOrSuperCategoriesFetching](false)
        return
      }
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: [
            'storeInventory',
            'superCategories',
            'genericCategories',
            'byWeightHomeCodes',
            'airtimeProviders',
            'airtimeServices',
          ],
          replyName: 'fetchProducts',
        },
      })
    },
    resetScannerStatus(group) {
      if (group === undefined) return
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[productsViewActions.setSearchTermFilter](null)
          this[productsViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[productsViewActions.setGroupFilter]('superCategories')
            : this[productsViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    setFilterIfRouteIsRequired() {
      if (!this.$route.query.filterBy) return
      this[productsViewActions.setGroupFilter](this.$route.query.filterBy)
      this.$router.replace({
        query: {},
      })
    },
  },
  created() {
    if (this.selectedUser.productsTourDisabled === 0)
      this[productsViewActions.setProductsTourEnabled](true)
  },
  mounted() {
    this.$root.$on('productAddedFromMatch', this.onBarcodeScanned)
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductListener
    )
    this.$barcodeScanner.init(this.onBarcodeScanned)
    this.searchInput = document.getElementById('product-input-search')
    if (this.data.products.length === 0) {
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ENTITIES_EVENTS.channel, {
        event: ENTITIES_EVENTS.events.getAllByEntities.name,
        data: {
          entitiesToGet: [
            'storeInventory',
            'superCategories',
            'genericCategories',
            'byWeightHomeCodes',
            'airtimeProviders',
            'airtimeServices',
          ],
          replyName: 'fetchProducts',
        },
      })
    } else {
      this.getLayoutHeight()
    }
    this[productsViewActions.setGroupFilter](this.defaultProductsFilter)
    this.setFilterIfRouteIsRequired()
    this[productsViewActions.setSearchTermFilter](null)
    if (this.isScannerActive === false) this[appActions.updateScannerStatus]()
    rendererEventsService.subscribe('products-menu-channel', (event, arg) => {
      switch (arg) {
        case 'products-scan':
          this.$root.$emit('reset')
          this[productsViewActions.setSearchTermFilter](null)
          this[productsViewActions.setSuperCategoriesFilter]([])
          this[appActions.updateScannerStatus]()
          this[productsViewActions.setGroupFilter](
            this.isScannerActive ? this.defaultProductsFilter : 'search'
          )
          !this.isScannerActive
            ? this.searchInput.focus()
            : this.searchInput.blur()
          break
      }
    })
    this.$root.$on('enable-scanner', () =>
      this.$barcodeScanner.init(this.onBarcodeScanned)
    )
    rendererEventsService.subscribe(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
    rendererEventsService.subscribe(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.downloadStoreInventoryListener
    )
    this.$watch(
      () => this.$route.query,
      () => {
        this.setFilterIfRouteIsRequired()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners('products-menu-channel')
    rendererEventsService.removeListener(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.downloadStoreInventoryListener
    )
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.addProductListener
    )
    rendererEventsService.removeListener(
      MLP_DB_API_EVENTS.replyChannel,
      this.mlpApiListener
    )
  },
  destroyed() {
    this.$root.$off('productAddedFromMatch', this.onBarcodeScanned)
    this.$barcodeScanner.destroy()
    this[productsViewActions.setSuperCategoriesFilter]([])
  },
}
</script>

<style lang="scss" scoped>
$window-status: 'default', 'minimum';

.products-view {
  height: 100%;
  .products-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .products-view__products-list {
    width: 100%;
  }
}
</style>
