<template>
  <div class="fill-height">
    <PaginatedCards :config="paginatedCardsConfig" id="products-products-list">
      <template v-slot:headerLeft>
        <DownloadHomeCodes />
      </template>
    </PaginatedCards>
    <SimilarProductsUpc v-if="similarProductsUpcDialog.isOpen" />
    <v-overlay
      :value="productDetailDialog.isOpen && selectedProduct"
      :z-index="isTourEnabled ? 198 : 201"
      opacity="0.15"
    >
      <div class="product-list__details">
        <v-btn
          v-if="showArrowsToNavigate && sortFilteredData.length > 1"
          fab
          color="accent"
          small
          @click="navigateToProduct = 'prev'"
        >
          <v-icon>mdi-chevron-left</v-icon>
        </v-btn>
        <v-dialog
          v-model="showProductDetails"
          max-width="715"
          :persistent="isTourEnabled"
          hide-overlay
          :transition="dialogTransition"
          :content-class="
            isTourEnabled ? 'below-tour default-dialog' : 'default-dialog'
          "
          @click:outside="onClickOutside"
          @input="hideOrNavigateToProduct"
        >
          <!-- Detail view -->
          <ProductDetail />
        </v-dialog>
        <v-btn
          v-if="showArrowsToNavigate && sortFilteredData.length > 1"
          fab
          color="accent"
          small
          @click="navigateToProduct = 'next'"
        >
          <v-icon>mdi-chevron-right</v-icon>
        </v-btn>
      </div>
    </v-overlay>
  </div>
</template>

<script>
import { isNil, concat } from 'ramda'
import { mapState, mapGetters, mapActions } from 'vuex'

import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'
import usersViewActions from '@/store/usersView/actions.types'

import PaginatedCards from '@/components/shared/PaginatedCards'
import ProductDetail from '@/components/ProductDetail'
import setConfig from '@/components/ProductsView/ProductsList/PaginatedCards/config'
import DownloadHomeCodes from '@/components/ProductsView/ProductsList/DownloadHomeCodes'
import SimilarProductsUpc from '@/components/ProductsView/ProductsList/SimilarProductsUpc'

export default {
  name: 'PaginatedCardsList',
  components: {
    SimilarProductsUpc,
    DownloadHomeCodes,
    PaginatedCards,
    ProductDetail,
  },
  props: {
    bulkDeletionConfig: {
      type: Object,
      default: null,
    },
  },
  data() {
    return {
      showProductDetails: false,
      showArrowsToNavigate: false,
      navigateToProduct: null,
      sortFilteredData: [],
      sortBy: null,
      sortDesc: false,
    }
  },
  computed: {
    ...mapState('app', ['windowSize', 'sidebarOpened']),
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('products', ['data', 'fetching']),
    ...mapState('productsView', [
      'filters',
      'selectedProduct',
      'cardComponent',
      'tourEnabled',
      'similarProductsUpcDialog',
    ]),
    ...mapState({
      productDetailDialog(state) {
        return state[this.getViewStore()].productDetailDialog
      },
    }),
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('products', ['getFilteredData']),
    filteredData() {
      const filteredData = concat(this.getFilteredData, this.data.mlp)
      const searchTerm = this.filters.searchTerm
      if (
        !isNil(searchTerm) &&
        this.isScannerActive === true &&
        filteredData.length === 0
      ) {
        if (searchTerm.length > 24) {
          this.$root.$emit('reset')
          this.resetScannerStatus(this.defaultProductsFilter)
          this[productsViewActions.setSearchTermFilter](null)
          return this.getFilteredData
        }
        this.tryAddProductFromMLP(searchTerm)
      }
      return filteredData
    },
    paginatedCardsConfig() {
      return setConfig(
        {
          items: this.filteredData,
          selectedCard: this.selectedProduct,
          filters: this.filters,
          windowHeight: this.windowSize.y,
          windowWidth: this.windowSize.x,
          fetching: this.fetching,
          sidebarOpened: this.sidebarOpened,
          currentCardComponent: this.cardComponent,
          bulkDeletion: this.bulkDeletionConfig,
          sortBy: this.sortBy,
          sortDesc: this.sortDesc,
        },
        {
          onSectionWidthChange: this.onSectionWidthChange,
          onClickCard: this.onClickCard,
          resetScannerStatus: this.resetScannerStatus,
          updateSortBy: value => (this.sortBy = value),
          updateSortDesc: value => (this.sortDesc = value),
        }
      )
    },
    isTourEnabled() {
      return this.tourEnabled
    },
    dialogTransition() {
      if (!this.navigateToProduct) return 'none'
      return this.navigateToProduct === 'next'
        ? 'slide-x-transition'
        : 'slide-x-reverse-transition'
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('productsView', [
      productsViewActions.toggleDetailDialog,
      productsViewActions.setSelectedProduct,
      productsViewActions.setSearchTermFilter,
      productsViewActions.setGroupFilter,
    ]),
    ...mapActions('products', [
      productsActions.setProductsOrSuperCategoriesFetching,
      productsActions.resetMlpFilteredProducts,
    ]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    getViewStore() {
      return this.$route.name === 'Products' ? 'productsView' : 'salesView'
    },
    onClickOutside() {
      if (this.navigateToProduct) return
      if (this.tourEnabled) return
      this[productsViewActions.toggleDetailDialog]()
      this[productsViewActions.setSelectedProduct](null)
      if (this.isScannerActive === true)
        this[productsViewActions.setSearchTermFilter](null)
      document.getElementById('clear-button-control').click()
    },
    tryAddProductFromMLP(upc) {
      if (this.fetching) return
      this[productsActions.setProductsOrSuperCategoriesFetching](true)
      rendererEventsService.send(ADD_PRODUCT_EVENTS.channel, {
        event: ADD_PRODUCT_EVENTS.events.addProductFromMLP.name,
        data: {
          item: { property: 'upc_code', value: upc, limit: 1 },
        },
      })
    },
    resetScannerStatus(group) {
      if (group === undefined) return
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[productsViewActions.setSearchTermFilter](null)
          this[productsViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[productsViewActions.setGroupFilter]('superCategories')
            : this[productsViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    onClickCard(item) {
      if (this.bulkDeletionConfig && this.bulkDeletionConfig.isActive) {
        if (!('storeId' in item)) return
        this.$track({
          type: 'interaction',
          action: 'click',
          category: 'Products',
          screen: 'ProductCard',
          name: `Select product to delete`,
        })
        this.bulkDeletionConfig.itemToBeDelete(item.id)
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Products',
        screen: 'ProductCard',
        name: `Open product details`,
      })
      if (this.tourEnabled) this.$root.$emit('product-added-products-tour')
      if (this.selectedUser.productsTourDisabled === 0 && !this.tourEnabled) {
        const selectedUser = Object.assign(this.selectedUser)
        rendererEventsService.send(USER_EVENTS.channel, {
          event: USER_EVENTS.events.update.name,
          data: {
            userId: selectedUser.id,
            values: { products_tour_disabled: 1 },
          },
        })
        selectedUser.productsTourDisabled = 1
        this[usersViewActions.setSelectedUser](selectedUser)
      }
      if (isNil(item.isStoreInventory) || item.isStoreInventory === 1) {
        this.setSortFilteredData()
        this.showArrowsToNavigate = true
        this[productsViewActions.setSelectedProduct](item)
        this[productsViewActions.toggleDetailDialog]()
        return
      }
      this.showArrowsToNavigate = false
      this.tryAddProductFromMLP(item.upc)
    },
    hideOrNavigateToProduct(value) {
      if (!value) this.onClickOutside()
      if (!this.navigateToProduct) return
      if (this.sortFilteredData.length <= 0) this.setSortFilteredData()
      setTimeout(() => (this.showProductDetails = true), 200)
      let productSelectedIndex = this.sortFilteredData.findIndex(
        prod => prod.id === this.selectedProduct.id
      )
      const productToNavigateIndex = this.getProductToNavigatePosition(
        productSelectedIndex
      )
      this[productsViewActions.setSelectedProduct](
        this.sortFilteredData[productToNavigateIndex]
      )
      this.$root.$emit('navigateToProductWasDone')
      setTimeout(() => (this.navigateToProduct = null), 250)
    },
    setSortFilteredData() {
      const productsStored = this.filteredData.filter(
        item => item.isStoreInventory !== 0
      )
      if (!this.sortBy) {
        this.sortFilteredData = productsStored
        return
      }
      this.sortFilteredData = productsStored.sort((productA, productB) => {
        let position = productA[this.sortBy] < productB[this.sortBy] ? -1 : 1
        if (productA[this.sortBy] === productB[this.sortBy] && this.sortDesc) {
          position = productA.id < productB.id ? 1 : -1
        }
        return this.sortDesc ? position * -1 : position
      })
    },
    getProductToNavigatePosition(productSelectedIndex) {
      const productToNavigateIndex =
        this.navigateToProduct === 'next'
          ? productSelectedIndex + 1
          : productSelectedIndex - 1
      if (productToNavigateIndex < 0) {
        return this.sortFilteredData.length - 1
      }
      if (productToNavigateIndex >= this.sortFilteredData.length) {
        return 0
      }
      return productToNavigateIndex
    },
  },
  watch: {
    sortBy() {
      this.setSortFilteredData()
    },
    sortDesc() {
      this.setSortFilteredData()
    },
  },
  mounted() {
    this.showProductDetails = this.productDetailDialog
      ? this.productDetailDialog.isOpen
      : false
    this.$watch(
      () => this.productDetailDialog.isOpen,
      newValue => {
        this.showProductDetails = newValue
      }
    )
  },
}
</script>

<style lang="scss" scoped>
.fill-height {
  :deep(.v-overlay__content) {
    width: 100%;
  }
}
.product-list__details {
  width: 100%;
  display: flex;
  justify-content: center;
  gap: 780px;
}
</style>
