<template>
  <div>
    <AlertNoDataToShow v-if="historyReport <= 0" />
    <div v-else :style="{ height: containerHeight + 'px' }">
      <PaginatedList :config="componentConfig">
        <template v-slot:item="{ item }">
          <DetailStockModification :stock-modification="item" />
        </template>
      </PaginatedList>
    </div>
    <DeleteStockModification />
  </div>
</template>

<script>
import STOCK_MODIFICATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/stockModificationsEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import PaginatedList from '@/components/shared/PaginatedTable'
import setConfig from '@/components/ProductDetail/HistoryTab/config'
import AlertNoDataToShow from '@/components/shared/AlertNoDataToShow'
import DetailStockModification from '@/components/ProductDetail/HistoryTab/DetailStockModification'
import DeleteStockModification from '@/components/ProductDetail/HistoryTab/DeleteStockModifcation'
import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'

export default {
  name: 'HistoryTab',
  components: {
    DeleteStockModification,
    DetailStockModification,
    AlertNoDataToShow,
    PaginatedList,
  },
  data() {
    return {
      historyReport: [],
      rowHeight: 65,
      containerHeight: 0,
    }
  },
  computed: {
    ...getSelectedProductByRoute(),
    componentConfig() {
      return setConfig(
        {
          items: this.historyReport,
          rowHeight: this.rowHeight,
        },
        {
          context: this,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    loadStockModifications() {
      rendererEventsService.send(STOCK_MODIFICATIONS_DB_API_EVENTS.channel, {
        event: STOCK_MODIFICATIONS_DB_API_EVENTS.events.getByProduct.name,
        data: { productId: this.selectedProduct.id },
      })
    },
    getCustomHeight() {
      const popupHeight = document.getElementById('product-detail-card')
        .offsetHeight
      const headerHeight = document.getElementById('product-detail-card-header')
        .offsetHeight
      const footerHeight = document.getElementById('product-detail-card-footer')
        .offsetHeight
      const tabHeaderHeight = document.getElementsByClassName(
        'v-slide-group__wrapper'
      )[0].offsetHeight
      this.containerHeight =
        popupHeight - headerHeight - footerHeight - tabHeaderHeight - 25
    },
    async stockModificationsListener(event, payload) {
      const events = STOCK_MODIFICATIONS_DB_API_EVENTS.events
      const replies = {
        [events.getByProduct.replies.success]: () => {
          this.historyReport = payload.data
        },
        [events.getByProduct.replies.error]: () => {
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          )
          this.historyReport = []
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      STOCK_MODIFICATIONS_DB_API_EVENTS.replyChannel,
      this.stockModificationsListener
    )
  },
  mounted() {
    this.loadStockModifications()
    this.getCustomHeight()
    this.$root.$on('navigateToProductWasDone', this.loadStockModifications)
    this.$root.$on('productStoreWasUpdated', this.loadStockModifications)
  },
  beforeDestroy() {
    this.$root.$on('navigateToProductWasDone', this.loadStockModifications)
    this.$root.$off('productStoreWasUpdated', this.loadStockModifications)
    rendererEventsService.removeListener(
      STOCK_MODIFICATIONS_DB_API_EVENTS.replyChannel,
      this.stockModificationsListener
    )
  },
}
</script>
