<template>
  <v-container fluid>
    <v-row>
      {{ productsImportedTotalText }}
    </v-row>
    <v-row>
      {{ productsUpdatedTotalText }}
    </v-row>
    <v-row class="mt-4">
      <FormattedText
        intl
        value="productsView.importProductsDialog.stepper.steps.step3.productsNoImported"
      />
      <PaginatedList
        :config="tableComponentConfig"
        class="table-products"
        :key="total"
      >
        <template v-slot:top>
          <div class="header-table" />
        </template>
      </PaginatedList>
    </v-row>
  </v-container>
</template>

<script>
import { mapState } from 'vuex'

import STORE_INVENTORY_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import setConfig from '@/components/ProductsView/ImportStoreInventoryDialog/ImportStepper/steps/ImportResult/config'
import PaginatedList from '@/components/shared/PaginatedTable'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'ImportResult',
  components: { PaginatedList, FormattedText },
  data() {
    return {
      productsImported: [],
      productsUpdated: [],
      invalidProducts: [],
      total: 0,
    }
  },
  computed: {
    ...mapState('app', ['windowSize']),
    productsImportedTotalText() {
      return `${this.getTranslatedText(
        'productsView.importProductsDialog.stepper.steps.step3.productsImported',
        [this.productsImported.length, this.total]
      )} `
    },
    productsUpdatedTotalText() {
      return `${this.getTranslatedText(
        'productsView.importProductsDialog.stepper.steps.step3.productsUpdated',
        [this.productsUpdated.length, this.total]
      )} `
    },
    tableComponentConfig() {
      return setConfig(
        {
          items: this.invalidProducts,
          windowHeight: this.windowSize.y,
        },
        {
          context: this,
          getTranslatedText: this.getTranslatedText,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    async storeInventoryListiner(event, payload) {
      const events = STORE_INVENTORY_EVENTS.events
      const replies = {
        [events.import.replies.success]: () => {
          const {
            productsImported,
            invalidProducts,
            productsUpdated,
            total,
          } = payload.data
          this.productsImported = productsImported
          this.invalidProducts = invalidProducts
          this.productsUpdated = productsUpdated
          this.total = total
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    rendererEventsService.subscribe(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.storeInventoryListiner
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      STORE_INVENTORY_EVENTS.replyChannel,
      this.storeInventoryListiner
    )
  },
}
</script>

<style lang="scss" scoped>
.table-products {
  width: 100%;
  height: 21.86rem;
}
.header-table {
  height: 0;
  margin: 0;
  padding: 0;
}
</style>
