import { mapActions, mapState } from 'vuex'

import { getActionsTypes, getViewStore } from '@/tools/view'

export const getSelectedProductByRoute = () => {
  return mapState({
    selectedProduct(state) {
      return state[getViewStore(this.$route.name)].selectedProduct
    },
  })
}

export const updateSelectedProductByRoute = () => {
  return mapActions({
    setSelectedProduct(dispatch, payload) {
      return dispatch(
        `${getViewStore(this.$route.name)}/${
          getActionsTypes(this.$route.name).setSelectedProduct
        }`,
        payload
      )
    },
  })
}

export const isOpenGramaje = product => {
  const { isGramaje, isGramajeFromMLP } = product
  return isGramaje || isGramajeFromMLP
}
