<template>
  <div class="d-flex flex-column">
    <div class="d-flex">
      <FormattedText
        intl
        :value="label"
        type="text-subtitle-2"
        color="textPrimary"
        :class="!reverse ? 'label-padding' : ''"
      />
      <v-icon
        :color="config.iconColor ? config.iconColor : 'accent'"
        small
        class="pl-2"
      >
        {{ labelIcon }}
      </v-icon>
    </div>
    <div :class="['d-flex', reverse ? 'justify-end' : '']">
      <FormattedText :value="value" type="text-h6" color="textPrimary" />
    </div>
  </div>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'SingleDataWidget',
  components: {
    FormattedText,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      label: this.config.label,
      labelIcon: this.config.labelIcon,
      reverse: this.config.reverse,
    }
  },
  computed: {
    value() {
      return this.config.value.toString()
    },
  },
}
</script>
