const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-alert-circle',
    title: 'productsView.history.delete.title',
    titleColor: 'textPrimary',
    height: 260,
    maxWidth: 500,
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.deleteOperation(),
  },
})

export default setConfig
