import { formatText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import light from '@/themes/light'
import dark from '@/themes/dark'

export const config = (state, methods) => ({
  state,
  methods: {
    ...methods,
    onClick: item => methods.onClickRow(item),
    onDblClick: () => null,
  },
  title: 'productsView.listView.title',
  icon: 'mdi-fridge-outline',
  loaderColor: { light: light.productLoader, dark: dark.productLoader },
  page: 1,
  rowStyle: item =>
    state.bulkDeletion.isActive &&
    state.bulkDeletion.getDeleteSelectConfig(item).isSelected
      ? 'background: rgba(255, 138, 128, 0.25)'
      : '',
  rowsPerPage: 6,
  rowOffsetHeight: 48,
  itemsPerRow: {
    withoutDetail: {
      lg: 3,
      xl: 4,
    },
  },
  headers: state.bulkDeletion.isActive
    ? getBulkDeletionHeaders(methods, state.bulkDeletion, state.items)
    : getDefaultHeaders(methods),
  sortBy: '',
  sortDesc: false,
  groups: [
    {
      id: 'all',
      icon: 'mdi-view-module',
      title: 'productsView.toolbar.buttons.all',
    },
    {
      id: 'services',
      icon: 'mdi-cellphone-arrow-down',
      title: 'productsView.toolbar.buttons.services',
    },
    {
      id: 'byWeight',
      icon: 'mdi-weight',
      title: 'productsView.toolbar.buttons.byWeight',
    },
    {
      id: 'openProducts',
      icon: 'mdi-package-variant',
      title: 'productsView.toolbar.buttons.openProducts',
    },
    {
      id: 'favorites',
      icon: 'mdi-cards-heart',
      title: 'productsView.toolbar.buttons.favorites',
    },
    {
      id: 'search',
      icon: 'mdi-magnify',
      title: 'productsView.toolbar.buttons.search',
    },
    {
      id: 'superCategories',
      icon: 'mdi-tag-outline',
      title: 'productsView.toolbar.buttons.superCategories',
    },
    {
      id: 'scan',
      icon: 'mdi-barcode',
      title: 'productsView.toolbar.buttons.scan',
    },
    {
      id: 'noStock',
      icon: 'mdi-package-variant-remove',
      title: 'productsView.toolbar.buttons.noStock',
    },
    {
      id: 'lowStock',
      icon: 'mdi-package-variant-minus',
      title: 'productsView.toolbar.buttons.lowStock',
    },
  ],
  isClickable: true,
})

const getDefaultHeaders = methods => [
  {
    text: methods.context.$vuetify.lang.t(
      '$vuetify.productsView.listView.sortBy.name'
    ),
    align: 'start',
    value: 'name',
    format: item => item,
  },
  {
    text: methods.context.$vuetify.lang.t(
      '$vuetify.productsView.listView.sortBy.upc'
    ),
    value: 'upc',
    format: item => item,
  },
  {
    text: methods.context.$vuetify.lang.t(
      '$vuetify.productsView.listView.sortBy.price'
    ),
    value: 'price',
    format: item => formatNumberFromDbToCurrency(item),
  },
  {
    text: methods.context.$vuetify.lang.t(
      '$vuetify.productsView.listView.sortBy.quantity'
    ),
    align: 'end',
    value: 'quantity',
    format: (value, item) =>
      formatText({
        value,
        type: 'stock',
        ...item,
      }),
  },
]

const getBulkDeletionHeaders = (methods, bulkDeletion, items) => [
  {
    text: '',
    value: 'id',
    icon: id => getIconBulkDeletionFromItem(getItem(items, id), bulkDeletion),
    format: () => '',
  },
  ...getDefaultHeaders(methods),
]

const getIconBulkDeletionFromItem = (item, bulkDeletion) => {
  if (!item) return { color: '', icon: '' }
  const deleteSelectionConfig = bulkDeletion.getDeleteSelectConfig(item)
  if (!Object.keys(deleteSelectionConfig).length) return { color: '', icon: '' }
  return {
    icon: deleteSelectionConfig.icon,
    color: deleteSelectionConfig.iconColor,
  }
}

const getItem = (items, id) => {
  return items.find(item => item.id === id)
}

export default config
