<template>
  <DialogCard :config="componentConfig.dialogData">
    <Form :config="componentConfig" />
  </DialogCard>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import { testMode } from '@/config/env'
import ANALYZER_API_EVENTS from '@/config/events/serversAPI/analyzerEvents'

import { cleanObjectObserver, getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsViewActions from '@/store/productsView/action.types'

import setConfig from '@/components/ProductDetail/Footer/ReportDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'

export default {
  name: 'ReportDialog',
  components: { DialogCard, Form },
  props: {
    product: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('productsView', ['reportDialog']),
    ...mapState('account', ['data']),
    componentConfig() {
      return setConfig(
        {
          isOpen: this.reportDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          product: this.product,
        },
        {
          reportProduct: this.reportProduct,
          closeDialog: this.closeDialog,
          getTranslatedText: this.getTranslatedText,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('productsView', [productsViewActions.setReportDialogStatus]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    reportProduct: function() {
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: this.$route.name,
        screen: 'ReportDialog',
        name: `Send report`,
      })
      const data = this.inputs
      data['pos'] = this.data.pos
      data['upc_code'] = this.product.upc
      rendererEventsService.send(ANALYZER_API_EVENTS.channel, {
        event: ANALYZER_API_EVENTS.events.sendPosProductIssueReportKeys.name,
        data,
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => {
        if (key in this.$v.inputs) this.$v.inputs[key].$reset()
      })
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[productsViewActions.setReportDialogStatus](false)
    },
  },
  validations() {
    return this.validators
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      ANALYZER_API_EVENTS.replyChannel,
      (event, payload) => {
        const events = ANALYZER_API_EVENTS.events
        const replies = {
          [events.sendPosProductIssueReportKeys.replies.success]: () => {
            this.closeDialog()
            notificationsService.showSuccess(
              'notification.products.reported',
              this.$vuetify.lang
            )
          },
          [events.sendPosProductIssueReportKeys.replies.error]: () =>
            notificationsService.showError(
              'notification.products.errorReporting',
              this.$vuetify.lang
            ),
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  mounted() {
    this.$root.$on('productDetailTabsWasChanged', () =>
      this[productsViewActions.setReportDialogStatus](false)
    )
    this.setProperties()
  },
  beforeDestroy() {
    this.$root.$emit('enable-scanner', {})
    this.$root.$off('productDetailTabsWasChanged', () =>
      this[productsViewActions.setReportDialogStatus](false)
    )
    rendererEventsService.removeAllListeners(ANALYZER_API_EVENTS.replyChannel)
    this[productsViewActions.setReportDialogStatus](false)
  },
}
</script>
