<template>
  <v-card
    class="pa-0 rounded-widget"
    color="cardBackgroundSecondary"
    flat
    id="stock-details"
  >
    <div class="py-1 pl-5 pr-1 d-flex widget-title">
      <v-icon color="textOverBackground">mdi-basket-fill</v-icon>
      <FormattedText
        intl
        type="text-body-1"
        color="textOverBackground"
        value="productsView.details.stock"
        class="pl-2 pt-1"
        className="font-weight-bold"
      />
      <v-spacer />
      <v-btn
        v-if="widgetStatus !== null"
        @click="onClickDropDown"
        elevation="0"
        color="productSecondary"
        small
        class="pt-1"
      >
        <v-icon>
          {{ widgetStatus ? 'mdi-chevron-down' : 'mdi-chevron-right' }}
        </v-icon>
      </v-btn>
    </div>
    <v-container
      class="pa-0"
      v-if="widgetStatus === null || widgetStatus === true"
    >
      <v-row>
        <v-col cols="7" class="d-flex flex-column px-8">
          <div class="d-flex">
            <div
              v-for="widget in widgetConfig.singleWidgets.firstSection"
              :key="widget.id"
            >
              <component
                v-if="widget.show"
                :is="widget.type"
                :config="widget"
                :class="widget.extraClasses"
              />
            </div>
          </div>
        </v-col>
        <v-col cols="5" class="px-8">
          <div class="d-flex justify-end">
            <div
              v-for="widget in widgetConfig.singleWidgets.secondSection"
              :key="widget.id"
            >
              <component :is="widget.type" :config="widget" />
            </div>
          </div>
        </v-col>
      </v-row>
    </v-container>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import { storeInventory } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import { getActionsTypes, getViewStore } from '@/tools/view'

import rendererEventsService from '@/services/renderer/rendererEvents'

import { getSelectedProductByRoute } from '@/components/ProductDetail/selectedProduct.tools'
import setConfig from '@/components/ProductDetail/DetailsTab/StockDetails/config'
import {
  setPackagesStockValue,
  setPiecesStockValue,
  setOpenProductStockValue,
  getPackagesStockValue,
  getPiecesStockValue,
} from '@/components/ProductDetail/DetailsTab/tools'
import FormattedText from '@/components/shared/FormattedText'
import SingleDataWidget from '@/components/shared/SingleDataWidget'
import SingleEditDataWidget from '@/components/shared/SingleEditDataWidget'

export default {
  name: 'StockDetails',
  components: {
    FormattedText,
    SingleDataWidget,
    SingleEditDataWidget,
  },
  props: {
    opened: {
      type: Boolean,
    },
    onClickDropDown: {
      type: Function,
    },
  },
  computed: {
    ...mapState('usersView', ['selectedUser']),
    ...getSelectedProductByRoute(),
    widgetStatus() {
      return this.opened
    },
    widgetConfig: function() {
      return setConfig(
        {
          product: this.selectedProduct,
          hasInventoryLimitation:
            this.selectedUser.id === 1 ||
            this.selectedUser.inventoryPermission === 0
              ? false
              : true,
          routeName: this.$route.name,
        },
        {
          setSelectedProductField: this.updateSelectedProductField,
          updateDatabase: this.editProduct,
          updatePiecesStock: this.updatePiecesStock,
          updatePackageStock: this.updatePackageStock,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions({
      updateSelectedProductField(dispatch, payload) {
        return dispatch(
          `${getViewStore(this.$route.name)}/${
            getActionsTypes(this.$route.name).updateSelectedProductField
          }`,
          payload
        )
      },
    }),
    async updatePiecesStock() {
      if (this.selectedProduct.factor > 0) {
        await setPiecesStockValue(
          { setSelectedProductField: this.updateSelectedProductField },
          this.selectedProduct.factor,
          this.selectedProduct.quantity,
          this.selectedProduct.piecesQuantity
        )
        await this.reCalculateOpenProductStockValues()
      }
      this.editProduct({
        id: this.selectedProduct.id,
        data: mapStoreObject(
          { quantity: this.selectedProduct.quantity },
          storeInventory,
          true
        ),
      })
    },
    async updatePackageStock() {
      await setPackagesStockValue(
        { setSelectedProductField: this.updateSelectedProductField },
        this.selectedProduct.factor,
        this.selectedProduct.quantity,
        this.selectedProduct.packagesQuantity
      )
      await this.reCalculateOpenProductStockValues()
      this.editProduct({
        id: this.selectedProduct.id,
        data: mapStoreObject(
          { quantity: this.selectedProduct.quantity },
          storeInventory,
          true
        ),
      })
    },
    async reCalculateOpenProductStockValues() {
      await setOpenProductStockValue(
        { setSelectedProductField: this.updateSelectedProductField },
        'packagesQuantity',
        getPackagesStockValue(
          this.selectedProduct.quantity,
          this.selectedProduct.factor
        )
      )
      await setOpenProductStockValue(
        { setSelectedProductField: this.updateSelectedProductField },
        'piecesQuantity',
        getPiecesStockValue(
          this.selectedProduct.quantity,
          this.selectedProduct.factor
        )
      )
    },
    editProduct(productToUpdated) {
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.updateById.name,
        data: {
          productToUpdated,
          username: this.selectedUser.name,
        },
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.rounded-widget {
  border-radius: 8px;
  .widget-title {
    background-color: var(--v-cardSecondary-base);
  }
}
</style>
