<template>
  <div class="file-uploader">
    <div
      v-if="files < maxFiles"
      class="drop-area unfilled"
      :class="{ 'drag-over': dragging }"
      @dragover.prevent
      @drop="handleDrop"
      @click="handleClick"
    >
      <v-icon>mdi-upload</v-icon>
      <FormattedText
        intl
        value="shared.dropArea"
        typeText="text-body-1"
        class="m-0"
      />
    </div>
    <div v-else class="drop-area filled">
      <FormattedText
        intl
        value="shared.uploadedFile"
        typeText="text-body-1"
        class="m-0 mb-2"
      />
      <CustomButton
        text="shared.cancel"
        intl
        textType="text-button"
        @click="cancelUpload"
        :disabled="isLoading"
      />
    </div>
    <input
      type="file"
      ref="fileInput"
      @change="handleFileInputChange"
      style="display: none;"
    />
    <FormattedText :value="errorMessage" color="error" v-if="errorMessage" />
  </div>
</template>

<script>
import { isNil } from 'ramda'

import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'

export default {
  name: 'FileInputWithDropArea',
  components: { FormattedText, CustomButton },
  props: {
    maxFiles: {
      type: Number,
      default: 1,
    },
    validTypes: {
      type: Array,
      default: () => [],
    },
    isLoading: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      files: [],
      dragging: false,
      errorMessage: '',
    }
  },
  methods: {
    getTranslatedText,
    handleClick() {
      this.$refs.fileInput.click()
    },
    handleDrop(evt) {
      evt.preventDefault()
      const files = evt.dataTransfer.files
      this.validateFiles(files)
    },
    handleFileInputChange(evt) {
      const files = evt.target.files
      this.validateFiles(files)
    },
    validateFiles(files) {
      const validFiles = []
      for (let file of files) {
        if (
          this.validTypes.length > 0 &&
          !this.validTypes.includes(file.type)
        ) {
          this.errorMessage = this.getTranslatedText('shared.invalidFileType')
          return
        }
        validFiles.push(file)
      }

      if (validFiles.length > this.maxFiles) {
        this.errorMessage = this.getTranslatedText(
          'shared.maxFilesError',
          this.maxFiles
        )
        return
      }
      if (!isNil(validFiles)) {
        this.errorMessage = ''
        this.handleFiles(validFiles)
      }
    },
    handleFiles(files) {
      this.files = [...this.files, ...files]
      this.$emit('files-updated', this.files)
    },
    handleDragOver(evt) {
      evt.preventDefault()
      this.dragging = true
    },
    handleDragLeave(evt) {
      evt.preventDefault()
      this.dragging = false
    },
    cancelUpload() {
      this.files = []
      this.errorMessage = ''
      this.$emit('files-updated', this.files)
    },
  },
}
</script>

<style lang="scss" scoped>
.file-uploader {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.drop-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 350px;
  height: 200px;
  border: 3px dashed var(--v-borderDropArea-base);
  border-radius: 5px;
  margin-bottom: 20px;
  cursor: pointer;
}
.unfilled:hover {
  border-color: var(--v-primary-base);
}
.unfilled.drag-over {
  border-color: var(--v-primary-base);
}
.unfilled:hover span,
.unfilled.drag-over span {
  color: var(--v-primary-base);
}
.unfilled:hover i,
.unfilled.drag-over i {
  color: var(--v-primary-base);
}
</style>
