<template>
  <div class="ml-3 d-flex" v-if="bulkDeletion.isActive">
    <CustomButton
      :text="getTranslatedText('productsView.bulkDeletion.buttonCancel')"
      color="accent"
      depressed
      @click="resetBulkDeletion"
      v-track:click="{
        category: 'Products',
        screen: 'PaginatedCards',
        name: 'Cancel bulk deletion',
      }"
    />
    <CustomButton
      :text="
        getTranslatedText(
          'productsView.bulkDeletion.buttonAccept',
          String(bulkDeletion.itemsToDelete.length)
        )
      "
      depressed
      color="error"
      class="ml-2"
      @click="acceptBulkDeletionIsClicked"
      v-track:click="{
        category: 'Products',
        screen: 'PaginatedCards',
        name: 'Accept bulk deletion',
      }"
    />
    <DialogCard :config="config.confirmDialogData" />
    <DialogCard :config="config.infoDialogData" />
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import STORE_INVENTORY_DB_API_EVENTS from '@/config/events/databaseAPI/storeInventoryEvents'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import { testMode } from '@/config/env'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import productsActions from '@/store/products/actions.types'
import productsViewActions from '@/store/productsView/action.types'
import salesActions from '@/store/sales/actions.types'

import DialogCard from '@/components/shared/DialogCard'
import { setConfig } from '@/components/ProductsView/ProductsList/BulkDeletion/config'
import CustomButton from '@/components/shared/CustomButton'

export default {
  name: 'BulkDeletion',
  components: { CustomButton, DialogCard },
  data() {
    return {
      productsToDeleteInSales: [],
      isFromBulkDeletion: false,
    }
  },
  computed: {
    ...mapState('productsView', ['bulkDeletion', 'productInSaleDialog']),
    ...mapState('sales', ['sales']),
    config() {
      return setConfig(
        {
          isOpen: this.bulkDeletion.dialogIsOpen,
          itemsToDelete: this.bulkDeletion.itemsToDelete,
          opened: this.productInSaleDialog.isOpen,
        },
        {
          closeDialog: this.closeDialogs,
          acceptDeleteProducts: this.openProductInSaleDialog,
          confirmInfoDialog: this.confirmInfoDialog,
        }
      )
    },
    itemsToDeleteCounter() {
      return String(this.bulkDeletion.itemsToDelete.length)
    },
  },
  methods: {
    ...mapActions('productsView', [
      productsViewActions.setItemsToDeleteInBulkDeletion,
      productsViewActions.setBulkDeletionStatus,
      productsViewActions.setBulkDeletionDialogStatus,
      productsViewActions.setProductInSaleDialogStatus,
    ]),
    ...mapActions('products', [productsActions.bulkProductDeletion]),
    ...mapActions('sales', [salesActions.removeProductFromAllSales]),
    getTranslatedText,
    bulkDeletionButtonWasClicked() {
      if (this.bulkDeletion.isActive) {
        this.resetBulkDeletion()
        return
      }
      this[productsViewActions.setBulkDeletionStatus](true)
    },
    acceptBulkDeletionIsClicked() {
      if (this.bulkDeletion.itemsToDelete.length === 0) {
        return
      }
      this[productsViewActions.setBulkDeletionDialogStatus](true)
    },
    openProductInSaleDialog() {
      this.isFromBulkDeletion = true
      this.sales.forEach(sale => {
        sale.items.forEach(item => {
          if (this.bulkDeletion.itemsToDelete.includes(item.id)) {
            this.productsToDeleteInSales.push(item)
          }
        })
      })
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.checkItemInDraftPurchases.name,
        data: {
          productsId: this.bulkDeletion.itemsToDelete,
        },
      })
    },
    async bulkDeleteProducts() {
      this.$loading.show('bulkDeletionProducts')
      await this.removeProductsFormAllSales()
      rendererEventsService.send(STORE_INVENTORY_DB_API_EVENTS.channel, {
        event: STORE_INVENTORY_DB_API_EVENTS.events.bulkDeletion.name,
        data: { products: this.bulkDeletion.itemsToDelete },
      })
      this.resetBulkDeletion()
    },
    async removeProductsFormAllSales() {
      for (let productInSale of this.productsToDeleteInSales) {
        await this[salesActions.removeProductFromAllSales]({
          product: productInSale,
        })
      }
    },
    resetBulkDeletion() {
      this[productsViewActions.setItemsToDeleteInBulkDeletion]([])
      this[productsViewActions.setBulkDeletionStatus](false)
      this.productsToDeleteInSales = []
      this.isFromBulkDeletion = false
      this.closeDialogs()
    },
    closeDialogs() {
      this[productsViewActions.setBulkDeletionDialogStatus](false)
      this[productsViewActions.setProductInSaleDialogStatus](false)
    },
    confirmInfoDialog() {
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.removeItemInDraftPurchases.name,
        data: { productsId: this.bulkDeletion.itemsToDelete },
      })
    },
    async purchaseOrderListener(event, payload) {
      const purchaseEvents = PURCHASES_DB_API_EVENTS.events
      const replies = {
        [purchaseEvents.checkItemInDraftPurchases.replies.success]: () => {
          if (!this.isFromBulkDeletion) return
          const { products } = payload.data
          this.productsToDeleteInSales.length || products.length > 0
            ? this[productsViewActions.setProductInSaleDialogStatus](true)
            : this.bulkDeleteProducts()
        },
        [purchaseEvents.checkItemInDraftPurchases.replies.error]: () => {
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
        [purchaseEvents.removeItemInDraftPurchases.replies.success]: () => {
          if (this.isFromBulkDeletion) this.bulkDeleteProducts()
        },
        [purchaseEvents.removeItemInDraftPurchases.replies.error]: () => {
          this.resetBulkDeletion()
          notificationsService.showError(
            'notification.products.errorDeleting',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    bulkDeletionStore(event, payload) {
      const replies = {
        [STORE_INVENTORY_DB_API_EVENTS.events.bulkDeletion.replies
          .success]: async () => {
          await this[productsActions.bulkProductDeletion](
            payload.data.productsDeleted
          )
          this.$loading.hide()
          notificationsService.showSuccess(
            payload.data.message,
            this.$vuetify.lang,
            {},
            [payload.data.productsDeleted.length]
          )
          this.$root.$emit(
            'productsWereBulkDeleted',
            payload.data.productsDeleted
          )
        },
        [STORE_INVENTORY_DB_API_EVENTS.events.bulkDeletion.replies
          .error]: () => {
          notificationsService.showError(
            payload.data.error.message,
            this.$vuetify.lang
          )
          this.$loading.hide()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.bulkDeletionStore
    )
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
  mounted() {
    this.$root.$on(
      'bulkDeletionButtonWasClicked',
      this.bulkDeletionButtonWasClicked
    )
  },
  beforeDestroy() {
    this.resetBulkDeletion()
    rendererEventsService.removeListener(
      STORE_INVENTORY_DB_API_EVENTS.replyChannel,
      this.bulkDeletionStore
    )
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOrderListener
    )
  },
  destroyed() {
    this.$root.$off(
      'bulkDeletionButtonWasClicked',
      this.bulkDeletionButtonWasClicked
    )
  },
}
</script>
