<template>
  <div>
    <div v-show="false" ref="tourProductsFirstStep">
      <div class="tour-first-step-content">
        <v-icon size="90" class="mb-6">
          mdi-fridge-outline
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.productsTour.firstStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.productsTour.firstStep.secondText') }}
        </h2>
      </div>
    </div>
    <div v-show="false" ref="tourProductsSecondStep">
      <div class="tour-third-step-content">
        <h2>
          {{ getTranslatedText('tour.productsTour.secondStep.firstText') }}
        </h2>
        <h3>
          {{ getTranslatedText('tour.productsTour.secondStep.secondText') }}
        </h3>
      </div>
    </div>
    <div v-show="false" ref="tourProductsFourthStep">
      <span>
        {{ getTranslatedText('tour.productsTour.fourthStep.text') }}
      </span>
      <ul>
        <li>
          {{ getTranslatedText('tour.productsTour.fourthStep.firstPoint') }}
        </li>
        <li>
          {{ getTranslatedText('tour.productsTour.fourthStep.secondPoint') }}
        </li>
      </ul>
    </div>
    <div v-show="false" ref="tourProductsEighthStep">
      <div class="tour-first-step-content">
        <v-icon size="90" class="mb-6">
          mdi-nutrition
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.productsTour.eighthStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.productsTour.eighthStep.secondText') }}
        </h2>
        <h2>
          {{ getTranslatedText('tour.productsTour.eighthStep.thirdText') }}
        </h2>
      </div>
    </div>
  </div>
</template>

<script>
import { mapActions, mapGetters, mapState } from 'vuex'

import productsTour from '@/config/tours/productsTour'
import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'

import { getTranslatedText } from '@/tools/data'
import tourTrackTools from '@/tools/tourTrack'

import tourService from '@/services/renderer/tour'
import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'
import usersViewActions from '@/store/usersView/actions.types'
import appActions from '@/store/app/actions.types'

export default {
  name: 'ProductsViewTour',
  computed: {
    ...mapState('products', { mlpProducts: state => state.data.mlp }),
    ...mapState('productsView', ['tourEnabled']),
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('products', ['getFilteredData']),
  },
  methods: {
    ...mapActions('productsView', [productsViewActions.setProductsTourEnabled]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    ...mapActions('app', [appActions.setConfirmCancelTourDialogStatus]),
    getTranslatedText,
    createAndStartTour() {
      this.tour = tourService.createTour(this, productsTour.tourOptions)
      tourService.addSteps(this, productsTour.steps)
      tourService.addCancelFunctionToSteps(this, this.confirmCancelTour)
      tourTrackTools.initTracks.call(this, 'Products')
      this.tour.steps[1].once('show', () => {
        setTimeout(
          () => document.getElementById('product-input-search').click(),
          400
        )
      })
      this.tour.on('cancel', () => {
        this.disabledProductsTour()
      })
      this.tour.on('complete', () => {
        this.disabledProductsTour()
      })
      this.tour.start()
    },
    confirmCancelTour() {
      this[appActions.setConfirmCancelTourDialogStatus]({
        isOpen: true,
        tour: this.tour,
      })
    },
    disabledProductsTour() {
      const selectedUser = Object.assign(this.selectedUser)
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.update.name,
        data: {
          userId: selectedUser.id,
          values: { products_tour_disabled: 1 },
        },
      })
      const popupButton = document.getElementById('product-detail-close-button')
      if (popupButton) popupButton.click()
      this[productsViewActions.setProductsTourEnabled](false)
      selectedUser.productsTourDisabled = 1
      this[usersViewActions.setSelectedUser](selectedUser)
    },
  },
  watch: {
    mlpProducts: function(value) {
      if (this.tourEnabled) {
        const currentStep = this.tour.getCurrentStep().id
        if (currentStep === 'tourProductsSecondStep' && value.length !== 0)
          this.tour.next()
      }
    },
  },
  mounted() {
    if (this.tourEnabled) this.createAndStartTour()
    this.$root.$on('product-scanned-products-tour', barcode => {
      if (!this.tourEnabled) return
      const currentStep = this.tour.getCurrentStep().id
      if (
        currentStep === 'tourProductsSecondStep' &&
        this.getFilteredData.some(prod => prod.upc.includes(barcode))
      ) {
        setTimeout(() => {
          this.tour.next()
        }, 300)
      }
    })
    this.$root.$on('product-added-products-tour', () => {
      const currentStep = this.tour.getCurrentStep().id
      if (this.tourEnabled && currentStep === 'tourProductsThirdStep') {
        setTimeout(() => {
          this.tour.next()
        }, 300)
      }
    })
  },
  beforeDestroy() {
    this.$root.$off('product-added-products-tour')
    this.$root.$off('product-scanned-products-tour')
    tourTrackTools.destroyTracks.call(this, 'Products')
  },
}
</script>
