import { required, integer } from 'vuelidate/lib/validators'

import productsVariables from '@/config/products'

import { getDecimalsCount } from '@/tools/numbersFormat'

export const setMoneyValidator = (valueLimit, decimalsLimit) => {
  return {
    required,
    minValue: value => value > 0,
    maxValue: value => value < valueLimit,
    maxDecimals: value => getDecimalsCount(value) <= decimalsLimit,
  }
}

export const setDefaultValidators = (
  maxValue = productsVariables.STOCK_MAX_VALUE
) => {
  return {
    required,
    minValue: value => value > 0,
    maxValue: value => value <= maxValue,
    integer,
  }
}
