<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { mapActions, mapState, mapGetters } from 'vuex'
import { isNil } from 'ramda'

import { testMode, isDevelopment } from '@/config/env'
import MLP_DB_API_EVENTS from '@/config/events/databaseAPI/mlpEvents'

import rendererEvents from '@/services/renderer/rendererEvents'
import rendererEventsService from '@/services/renderer/rendererEvents'

import productsViewActions from '@/store/productsView/action.types'
import productsActions from '@/store/products/actions.types'
import appActions from '@/store/app/actions.types'

import config from '@/components/ProductsView/ProductsToolbar/Filters/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'ProductsFilter',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  timer: null,
  computed: {
    ...mapState('app', {
      isScannerActive: state => state.scanner.isActive,
      defaultProductsFilter: state => state.defaultProductsFilter,
    }),
    ...mapState('products', {
      productsSimilarUpc: state => state.data.productsSimilarUpc,
    }),
    ...mapState('products', ['data']),
    ...mapState('productsView', ['filters', 'tourEnabled']),
    ...mapGetters('products', ['getFilteredData']),
    componentConfig: function() {
      return config(
        {
          data: this.data,
          filters: this.filters,
          isScannerActive: this.isScannerActive,
          showProductsSimilarUpc: !!Object.keys(this.productsSimilarUpc).length,
        },
        {
          setSearchTerm: this[productsViewActions.setSearchTermFilter],
          onChange: this.onChange,
          onEnter: this.onEnter,
          setGroup: this[productsViewActions.setGroupFilter],
          setSelectedSuperCategories: this[
            productsViewActions.setSuperCategoriesFilter
          ],
          onReset: this.onReset,
          resetScannerStatus: this.resetScannerStatus,
          updateScannerStatus: this[appActions.updateScannerStatus],
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [appActions.updateScannerStatus]),
    ...mapActions('productsView', [
      productsViewActions.setGroupFilter,
      productsViewActions.setSearchTermFilter,
      productsViewActions.setSuperCategoriesFilter,
      productsViewActions.toggleAddProductDialog,
    ]),
    ...mapActions('products', [productsActions.resetMlpFilteredProducts]),
    onReset: function() {
      this.$root.$emit('reset')
    },
    resetScannerStatus(group) {
      switch (group) {
        case 'search-control':
          if (this.isScannerActive === false)
            this[appActions.updateScannerStatus]()
          break
        case 'clear':
          this[productsViewActions.setSearchTermFilter](null)
          this[productsViewActions.setGroupFilter](this.defaultProductsFilter)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
        default:
          group === 'superCategories'
            ? this[productsViewActions.setGroupFilter]('superCategories')
            : this[productsViewActions.setGroupFilter](group)
          if (!this.isScannerActive) this[appActions.updateScannerStatus]()
          break
      }
    },
    onChange(value) {
      const parsedValue = value === '' ? null : value
      if (this.filters.group === 'search') {
        this[productsViewActions.setSearchTermFilter](parsedValue)
      }
    },
    onEnter(value) {
      const parsedValue = value === '' ? null : value
      if (isDevelopment === false || value.length > 24 || this.tourEnabled)
        return
      if (
        this.getFilteredData.length === 0 &&
        this.data.mlp.length === 0 &&
        !isNil(parsedValue)
      )
        this[productsViewActions.toggleAddProductDialog]()
    },
  },
  watch: {
    'filters.searchTerm'(newValue) {
      const parsedValue = newValue === '' ? null : newValue
      if (isNil(parsedValue)) {
        this[productsActions.resetMlpFilteredProducts]([])
        return
      }
      if (this.timer) clearTimeout(this.timer)
      if (this.filters.group === 'search') {
        this.timer = setTimeout(() => {
          rendererEventsService.send(MLP_DB_API_EVENTS.channel, {
            event: MLP_DB_API_EVENTS.events.findByPropertiesLikes.name,
            data: [
              { key: 'upc_code', value: parsedValue },
              { key: 'prod_name', value: parsedValue },
            ],
          })
        }, 500)
      }
    },
  },
  mounted() {
    if (isNil(testMode))
      rendererEvents.subscribe('products-menu-channel', (event, arg) => {
        switch (arg) {
          case 'products-search':
            document.getElementById('product-input-search').click()
            break
          case 'products-all':
            document.getElementById('all-button-control').click()
            break
          case 'products-byWeight':
            document.getElementById('byWeight-button-control').click()
            break
          case 'products-favorites':
            document.getElementById('favorites-button-control').click()
            break
          case 'products-clear':
            document.getElementById('clear-button-control').click()
            break
        }
      })
  },
}
</script>
