export const setConfig = (state, methods) => ({
  state,
  methods,
  confirmDialogData: {
    opened: state.isOpen,
    icon: 'mdi-alert-circle',
    title: 'productsView.bulkDeletion.deletionTitle',
    messages: ['productsView.bulkDeletion.deletionConfirmation'],
    extraValuesMessages: [state.itemsToDelete.length],
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.acceptDeleteProducts(),
  },
  infoDialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'productsView.details.productInSaleDialog.title',
    titleBackground: '',
    titleColor: 'textPrimary',
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    persistent: true,
    messages: ['productsView.details.productInSaleDialog.message'],
    maxWidth: 500,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.confirmInfoDialog(),
  },
})
