const config = (state, methods) => {
  return {
    state,
    methods,
    groupClass: 'pr-4',
    groups: [
      {
        id: 'filters-group-01',
        controls: [
          {
            id: 'search-control',
            type: 'input',
            label: 'productsView.toolbar.searchField.label',
            placeholder: 'productsView.toolbar.searchField.placeholder',
            icon: 'mdi-magnify',
            backgroundColor: 'cardBackgroundSecondary',
            color: 'accent',
            ref: 'product-input-search',
            group: 'search',
            onChange: value => methods.onChange(value),
            onEnter: value => methods.onEnter(value),
            onClick: resetSelector => {
              state.isScannerActive === true
                ? methods.updateScannerStatus()
                : null
              resetSelector()
              methods.setGroup('search')
              methods.setSelectedSuperCategories([])
            },
          },
        ],
      },
      {
        id: 'filters-group-02',
        controls: [
          {
            id: 'all-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.all',
            icon: 'mdi-view-module',
            group: 'all',
            color:
              state.filters.group === 'all'
                ? 'accent lighten-1'
                : 'salesPrimary',
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect('all', methods, resetSelector, resetSearchTerm)
            },
          },
          // {
          //   id: 'services-button-control',
          //   type: 'button',
          //   label: 'productsView.toolbar.buttons.services',
          //   icon: 'mdi-cellphone-arrow-down',
          //   group: 'services',
          //   color: 'productPrimary',
          //   onClick: (resetSelector, resetSearchTerm) => {
          //     buttonEffect(
          //       'services',
          //       methods,
          //       resetSelector,
          //       resetSearchTerm,
          //       state
          //     )
          //   },
          // },
          {
            id: 'byWeight-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.byWeight',
            icon: 'mdi-weight',
            group: 'byWeight',
            color:
              state.filters.group === 'byWeight'
                ? 'accent lighten-1'
                : 'salesPrimary',
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect(
                'byWeight',
                methods,
                resetSelector,
                resetSearchTerm,
                state
              )
            },
          },
          {
            id: 'openProducts-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.openProducts',
            icon: 'mdi-package-variant',
            group: 'openProducts',
            color:
              state.filters.group === 'openProducts'
                ? 'accent lighten-1'
                : 'salesPrimary',
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect(
                'openProducts',
                methods,
                resetSelector,
                resetSearchTerm,
                state
              )
            },
          },
          {
            id: 'favorites-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.favorites',
            icon: 'mdi-cards-heart',
            group: 'favorites',
            color:
              state.filters.group === 'favorites'
                ? 'accent lighten-1'
                : 'salesPrimary',
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect(
                'favorites',
                methods,
                resetSelector,
                resetSearchTerm,
                state
              )
            },
          },
          {
            id: 'products-similar-upc-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.productsSimilarUpc',
            icon: 'mdi-alert',
            group: 'productsSimilarUpc',
            show: state.showProductsSimilarUpc,
            color:
              state.filters.group === 'productsSimilarUpc'
                ? 'accent lighten-1'
                : 'salesPrimary',
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect(
                'productsSimilarUpc',
                methods,
                resetSelector,
                resetSearchTerm,
                state
              )
            },
          },
        ],
      },
      {
        id: 'filters-group-03',
        controls: [
          {
            id: 'superCategories-select-control',
            type: 'select',
            label: 'productsView.toolbar.selectCategoryField.label',
            group: 'superCategories',
            items: state.data.superCategories,
            stringValueSelected:
              'productsView.toolbar.selectCategoryField.categoriesSelected',
            backgroundColor: 'cardBackgroundSecondary',
            limit: 3,
            width: 285,
            onChange: data => methods.setSelectedSuperCategories(data),
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect(
                'superCategories',
                methods,
                resetSelector,
                resetSearchTerm
              )
            },
          },
        ],
      },
      {
        id: 'filters-group-04',
        controls: [
          {
            id: 'clear-button-control',
            type: 'button',
            label: 'productsView.toolbar.buttons.clear',
            icon: 'mdi-close-circle',
            group: 'clear',
            color: 'accent',
            onClick: (resetSelector, resetSearchTerm) => {
              buttonEffect('clear', methods, resetSelector, resetSearchTerm)
            },
          },
        ],
      },
    ],
  }
}

const buttonEffect = (group, methods, resetSelector, resetSearchTerm) => {
  group === 'clear' ? methods.setGroup('all') : methods.setGroup(group)
  resetSelector()
  resetSearchTerm(null)
  methods.setSearchTerm(null)
  methods.setSelectedSuperCategories([])
  methods.resetScannerStatus(group)
}

export default config
